1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Bookmarks — prototype 1</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
11	    margin: 0; background: #f4f5f7; color: #1a1a2e;
12	  }
13	  header {
14	    background: #fff; border-bottom: 1px solid #e3e5e8;
15	    padding: 18px 28px; position: sticky; top: 0; z-index: 5;
16	  }
17	  h1 { font-size: 20px; margin: 0 0 14px; }
18	  .savebar { display: flex; gap: 8px; }
19	  .savebar input {
20	    flex: 1; padding: 11px 14px; font-size: 15px;
21	    border: 1px solid #cfd3d8; border-radius: 8px;
22	  }
23	  .savebar button {
24	    padding: 11px 20px; font-size: 15px; font-weight: 600;
25	    background: #2f6fed; color: #fff; border: none; border-radius: 8px; cursor: pointer;
26	  }
27	  .savebar button:hover { background: #235bce; }
28	  main { max-width: 900px; margin: 0 auto; padding: 22px 28px 60px; }
29	  .searchrow { position: relative; margin-bottom: 20px; }
30	  .searchrow input {
31	    width: 100%; padding: 12px 14px 12px 40px; font-size: 15px;
32	    border: 1px solid #cfd3d8; border-radius: 10px; background: #fff;
33	  }
34	  .searchrow .mag {
35	    position: absolute; left: 14px; top: 50%; transform: translateY(-50%);
36	    color: #9aa1ab; font-size: 16px;
37	  }
38	  .count { color: #6b7280; font-size: 13px; margin: 0 0 14px 2px; }
39	  .card {
40	    display: flex; gap: 14px; background: #fff; border: 1px solid #e3e5e8;
41	    border-radius: 12px; padding: 14px; margin-bottom: 12px; animation: pop .25s ease;
42	  }
43	  @keyframes pop { from { opacity: 0; transform: translateY(6px);} to {opacity:1;transform:none;} }
44	  .card.new { border-color: #2f6fed; box-shadow: 0 0 0 3px rgba(47,111,237,.12); }
45	  .thumb {
46	    width: 108px; height: 76px; flex: none; border-radius: 8px; object-fit: cover;
47	    background: #e9ebef;
48	  }
49	  .body { min-width: 0; }
50	  .body .title { font-size: 16px; font-weight: 600; margin: 2px 0 4px; }
51	  .body .url { font-size: 12.5px; color: #2f6fed; margin: 0 0 6px; word-break: break-all; }
52	  .body .desc { font-size: 13.5px; color: #4b5563; margin: 0; line-height: 1.45; }
53	  mark { background: #fff2a8; padding: 0 1px; border-radius: 3px; }
54	  .empty { text-align: center; color: #9aa1ab; padding: 50px 0; font-size: 15px; }
55	  .toast {
56	    position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
57	    background: #1a1a2e; color: #fff; padding: 12px 20px; border-radius: 10px;
58	    font-size: 14px; opacity: 0; pointer-events: none; transition: opacity .2s;
59	  }
60	  .toast.show { opacity: 1; }
61	</style>
62	</head>
63	<body>
64	<header>
65	  <h1>My Bookmarks</h1>
66	  <div class="savebar">
67	    <input id="urlInput" type="text" placeholder="Paste a link to save…" autocomplete="off">
68	    <button id="saveBtn">Save</button>
69	  </div>
70	</header>
71	
72	<main>
73	  <div class="searchrow">
74	    <span class="mag">⌕</span>
75	    <input id="searchInput" type="text" placeholder="Search everything you saved…" autocomplete="off">
76	  </div>
77	  <p class="count" id="count"></p>
78	  <div id="list"></div>
79	</main>
80	
81	<div class="toast" id="toast"></div>
82	
83	<script>
84	// --- seed data: things "saved a while ago", varied so search over more-than-title matters
85	let bookmarks = [
86	  { id: 1, title: "The Sourdough Starter Guide for Beginners",
87	    url: "https://kitchenlab.example/sourdough-starter",
88	    desc: "How to make and maintain a wild-yeast starter. Covers feeding schedules, the float test, and troubleshooting a starter that won't rise.",
89	    img: "https://picsum.photos/seed/bread/216/152" },
90	  { id: 2, title: "Understanding CSS Grid Layout",
91	    url: "https://webnotes.example/css-grid-deep-dive",
92	    desc: "A visual walkthrough of grid-template-areas, fractional units, and building a responsive photo gallery without media queries.",
93	    img: "https://picsum.photos/seed/grid/216/152" },
94	  { id: 3, title: "Why We Sleep — key takeaways",
95	    url: "https://readingnook.example/why-we-sleep-notes",
96	    desc: "Notes on Matthew Walker's book. The role of deep sleep in memory, caffeine's half-life, and the danger of chronic sleep debt.",
97	    img: "https://picsum.photos/seed/sleep/216/152" },
98	  { id: 4, title: "12 Hidden Gems in Lisbon",
99	    url: "https://travelmore.example/lisbon-hidden-gems",
100	    desc: "Neighbourhood viewpoints, a family-run tram cafe, and the best pastel de nata away from the tourist crowds.",
101	    img: "https://picsum.photos/seed/lisbon/216/152" },
102	  { id: 5, title: "A Practical Guide to Index Funds",
103	    url: "https://moneywise.example/index-funds-101",
104	    desc: "What an expense ratio really costs you over 30 years, dollar-cost averaging, and why most active funds underperform.",
105	    img: "https://picsum.photos/seed/money/216/152" },
106	];
107	
108	// --- simulated auto-capture: paste any URL, the app "fetches" title/image/desc for you
109	const canned = {
110	  "https://kitchenlab.example/no-knead-bread": {
111	    title: "No-Knead Bread in a Dutch Oven",
112	    desc: "A four-ingredient loaf with a crackly crust and open crumb. Long overnight rise, no kneading, baked in a covered pot.",
113	    img: "https://picsum.photos/seed/dutchoven/216/152" },
114	};
115	function autoCapture(url) {
116	  if (canned[url]) return canned[url];
117	  let host = "the page";
118	  try { host = new URL(url).hostname.replace(/^www\./,''); } catch(e){}
119	  const seed = encodeURIComponent(url).slice(-12) || "link";
120	  return {
121	    title: "Saved page from " + host,
122	    desc: "We grabbed this automatically from " + host + ". You didn't have to type any of it in.",
123	    img: "https://picsum.photos/seed/" + seed + "/216/152"
124	  };
125	}
126	
127	const listEl = document.getElementById('list');
128	const countEl = document.getElementById('count');
129	const searchEl = document.getElementById('searchInput');
130	let lastNewId = null;
131	
132	function esc(s){ return s.replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
133	function highlight(text, q){
134	  const safe = esc(text);
135	  if(!q) return safe;
136	  const re = new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
137	  return safe.replace(re, '<mark>$1</mark>');
138	}
139	
140	function render(){
141	  const q = searchEl.value.trim();
142	  const ql = q.toLowerCase();
143	  const matches = bookmarks.filter(b => !ql ||
144	    b.title.toLowerCase().includes(ql) ||
145	    b.url.toLowerCase().includes(ql) ||
146	    b.desc.toLowerCase().includes(ql));
147	
148	  if(matches.length === 0){
149	    countEl.textContent = '';
150	    listEl.innerHTML = '<div class="empty">Nothing matched “'+esc(q)+'”.</div>';
151	    return;
152	  }
153	  countEl.textContent = q
154	    ? matches.length + ' of ' + bookmarks.length + ' match'
155	    : bookmarks.length + ' saved';
156	
157	  listEl.innerHTML = matches.slice().reverse().map(b => `
158	    <div class="card ${b.id===lastNewId?'new':''}">
159	      <img class="thumb" src="${b.img}" alt="">
160	      <div class="body">
161	        <div class="title">${highlight(b.title, q)}</div>
162	        <div class="url">${highlight(b.url, q)}</div>
163	        <div class="desc">${highlight(b.desc, q)}</div>
164	      </div>
165	    </div>`).join('');
166	}
167	
168	function toast(msg){
169	  const t = document.getElementById('toast');
170	  t.textContent = msg; t.classList.add('show');
171	  setTimeout(()=>t.classList.remove('show'), 2200);
172	}
173	
174	document.getElementById('saveBtn').addEventListener('click', ()=>{
175	  const url = document.getElementById('urlInput').value.trim();
176	  if(!url) return;
177	  const cap = autoCapture(url);
178	  const id = Date.now();
179	  bookmarks.push({ id, url, title: cap.title, desc: cap.desc, img: cap.img });
180	  lastNewId = id;
181	  document.getElementById('urlInput').value = '';
182	  searchEl.value = '';
183	  render();
184	  toast('Saved — title and image grabbed automatically');
185	});
186	document.getElementById('urlInput').addEventListener('keydown', e=>{
187	  if(e.key==='Enter') document.getElementById('saveBtn').click();
188	});
189	searchEl.addEventListener('input', ()=>{ lastNewId=null; render(); });
190	
191	render();
192	</script>
193	</body>
194	</html>
