101	<header>
102	  <h1>My Bookmarks</h1>
103	  <div class="savebar">
104	    <input id="urlInput" type="text" placeholder="Paste a link to save…" autocomplete="off">
105	    <button id="saveBtn">Save</button>
106	  </div>
107	</header>
108	
109	<main>
110	  <div class="searchrow">
111	    <span class="mag">⌕</span>
112	    <input id="searchInput" type="text" placeholder="Search everything you saved…" autocomplete="off">
113	  </div>
114	  <p class="count" id="count"></p>
115	  <div id="list"></div>
116	</main>
117	
118	<div class="toast" id="toast"></div>
119	
120	<div class="browser" id="browser">
121	  <div class="win">
122	    <div class="chrome">
123	      <div class="dots"><span></span><span></span><span></span></div>
124	      <div class="addr" id="addr"></div>
125	      <div class="closex" id="closeBrowser">✕</div>
126	    </div>
127	    <div class="page">
128	      <h2 id="pageTitle"></h2>
129	      <p id="pageBody"></p>
130	      <p class="hint">(Simulated: in the real app this is the actual web page opening. Close this to go back.)</p>
131	    </div>
132	  </div>
133	</div>
134	
135	<script>
136	let bookmarks = [
137	  { id: 1, title: "The Sourdough Starter Guide for Beginners",
138	    url: "https://kitchenlab.example/sourdough-starter",
139	    desc: "How to make and maintain a wild-yeast starter. Covers feeding schedules, the float test, and troubleshooting a starter that won't rise.",
140	    img: "https://picsum.photos/seed/bread/216/152" },
141	  { id: 2, title: "Understanding CSS Grid Layout",
142	    url: "https://webnotes.example/css-grid-deep-dive",
143	    desc: "A visual walkthrough of grid-template-areas, fractional units, and building a responsive photo gallery without media queries.",
144	    img: "https://picsum.photos/seed/grid/216/152" },
145	  { id: 3, title: "Why We Sleep — key takeaways",
146	    url: "https://readingnook.example/why-we-sleep-notes",
147	    desc: "Notes on Matthew Walker's book. The role of deep sleep in memory, caffeine's half-life, and the danger of chronic sleep debt.",
148	    img: "https://picsum.photos/seed/sleep/216/152" },
149	  { id: 4, title: "12 Hidden Gems in Lisbon",
150	    url: "https://travelmore.example/lisbon-hidden-gems",
151	    desc: "Neighbourhood viewpoints, a family-run tram cafe, and the best pastel de nata away from the tourist crowds.",
152	    img: "https://picsum.photos/seed/lisbon/216/152" },
153	  { id: 5, title: "A Practical Guide to Index Funds",
154	    url: "https://moneywise.example/index-funds-101",
155	    desc: "What an expense ratio really costs you over 30 years, dollar-cost averaging, and why most active funds underperform.",
156	    img: "https://picsum.photos/seed/money/216/152" },
157	];
158	
159	const canned = {
160	  "https://kitchenlab.example/no-knead-bread": {
161	    title: "No-Knead Bread in a Dutch Oven",
162	    desc: "A four-ingredient loaf with a crackly crust and open crumb. Long overnight rise, no kneading, baked in a covered pot.",
163	    img: "https://picsum.photos/seed/dutchoven/216/152" },
164	};
165	function autoCapture(url) {
166	  if (canned[url]) return canned[url];
167	  let host = "the page";
168	  try { host = new URL(url).hostname.replace(/^www\./,''); } catch(e){}
169	  const seed = encodeURIComponent(url).slice(-12) || "link";
170	  return {
171	    title: "Saved page from " + host,
172	    desc: "We grabbed this automatically from " + host + ". You didn't have to type any of it in.",
173	    img: "https://picsum.photos/seed/" + seed + "/216/152"
174	  };
175	}
176	// normalize a URL so trivial differences don't count as new (dedupe)
177	function normUrl(u){
178	  let s = u.trim().toLowerCase();
179	  s = s.replace(/\/+$/,'');            // trailing slashes
180	  s = s.replace(/^https?:\/\//,'');    // scheme
181	  s = s.replace(/^www\./,'');          // www
182	  return s;
183	}
184	
185	const listEl = document.getElementById('list');
186	const countEl = document.getElementById('count');
187	const searchEl = document.getElementById('searchInput');
188	let lastNewId = null;
189	let editingId = null;
190	let flashId = null;
191	
192	function esc(s){ return s.replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
193	function highlight(text, q){
194	  const safe = esc(text);
195	  if(!q) return safe;
