197	  return safe.replace(re, '<mark>$1</mark>');
198	}
199	
200	function cardHtml(b, q, isNew){
201	  if(b.id === editingId){
202	    return `
203	    <div class="card ${isNew?'new':''}" data-id="${b.id}">
204	      <img class="thumb" src="${b.img}" alt="">
205	      <div class="body">
206	        ${isNew?'<p class="savenote">Saved — the details below were filled in for you. Fix anything you like.</p>':''}
207	        <div class="edit-form">
208	          <div class="lbl">Title</div>
209	          <input class="e-title" type="text" value="${esc(b.title)}">
210	          <div class="lbl">Summary</div>
211	          <textarea class="e-desc">${esc(b.desc)}</textarea>
212	          <div class="edit-actions">
213	            <button class="save" data-act="commit">Save changes</button>
214	            <button class="cancel" data-act="cancel">Cancel</button>
215	          </div>
216	        </div>
217	      </div>
218	    </div>`;
219	  }
220	  return `
221	    <div class="card ${isNew?'new':''} ${b.id===flashId?'flash':''}" data-id="${b.id}">
222	      <img class="thumb clickable" src="${b.img}" alt="" data-act="open">
223	      <button class="edit-btn" data-act="edit">Edit</button>
224	      <div class="body clickable" data-act="open">
225	        <div class="title">${highlight(b.title, q)}</div>
226	        <div class="url">${highlight(b.url, q)}</div>
227	        <div class="desc">${highlight(b.desc, q)}</div>
228	      </div>
229	    </div>`;
230	}
231	
232	function render(){
233	  const q = searchEl.value.trim();
234	  const ql = q.toLowerCase();
235	  const matches = bookmarks.filter(b => !ql ||
236	    b.title.toLowerCase().includes(ql) ||
237	    b.url.toLowerCase().includes(ql) ||
238	    b.desc.toLowerCase().includes(ql));
239	
240	  if(matches.length === 0){
241	    countEl.textContent = '';
242	    listEl.innerHTML = '<div class="empty">Nothing matched “'+esc(q)+'”.</div>';
243	    return;
244	  }
245	  countEl.textContent = q
246	    ? matches.length + ' of ' + bookmarks.length + ' match'
247	    : bookmarks.length + ' saved';
248	
249	  listEl.innerHTML = matches.slice().reverse()
250	    .map(b => cardHtml(b, q, b.id===lastNewId)).join('');
251	  flashId = null;
252	}
253	
254	function toast(msg){
255	  const t = document.getElementById('toast');
256	  t.textContent = msg; t.classList.add('show');
257	  setTimeout(()=>t.classList.remove('show'), 2400);
258	}
259	
260	function openPage(b){
261	  document.getElementById('addr').textContent = b.url;
