49	  .chip { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; padding: 3px 4px 3px 10px; border-radius: 999px; background: #d9e5ff; color: #1c4fbf; }
50	  .chip button { border: none; background: transparent; color: #1c4fbf; cursor: pointer; font-size: 13px; line-height: 1; padding: 0 3px; }
