55	  .edit-actions .save { background: #2f6fed; color: #fff; border: none; border-radius: 7px; padding: 7px 16px; font-weight: 600; cursor: pointer; }
56	  .edit-actions .cancel { background: #fff; color: #4b5563; border: 1px solid #cfd3d8; border-radius: 7px; padding: 7px 16px; cursor: pointer; }
57	  .edit-actions .delete { margin-left: auto; background: #fff; color: #c0392b; border: 1px solid #e6c3bd; border-radius: 7px; padding: 7px 16px; cursor: pointer; }
58	  .edit-actions .delete:hover { background: #fdeeec; }
59	  .savenote { font-size: 12.5px; color: #2f6fed; margin: 0 0 8px; }
60	  .empty { text-align: center; color: #9aa1ab; padding: 50px 0; font-size: 15px; }
61	  .toast { position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); background: #1a1a2e; color: #fff; padding: 12px 18px; border-radius: 10px; font-size: 14px; opacity: 0; pointer-events: none; transition: opacity .2s; z-index: 50; display: flex; align-items: center; gap: 14px; }
62	  .toast.show { opacity: 1; pointer-events: auto; }
63	  .toast button { background: transparent; color: #ffd54a; border: none; font-weight: 700; cursor: pointer; font-size: 14px; }
64	  .browser { position: fixed; inset: 0; background: rgba(0,0,0,.45); z-index: 40; display: none; align-items: flex-start; justify-content: center; padding: 40px 20px; }
65	  .browser.show { display: flex; }
66	  .win { background: #fff; width: 100%; max-width: 760px; border-radius: 12px; overflow: hidden; box-shadow: 0 20px 60px rgba(0,0,0,.35); }
67	  .chrome { display: flex; align-items: center; gap: 10px; background: #ececf0; padding: 10px 14px; border-bottom: 1px solid #dcdee3; }
68	  .dots { display: flex; gap: 6px; } .dots span { width: 11px; height: 11px; border-radius: 50%; background: #c9ccd2; }
69	  .addr { flex: 1; background: #fff; border-radius: 7px; padding: 6px 12px; font-size: 12.5px; color: #4b5563; border: 1px solid #dcdee3; }
70	  .closex { cursor: pointer; color: #6b7280; font-size: 18px; padding: 0 4px; }
71	  .page { padding: 34px 40px 46px; } .page h2 { margin: 0 0 10px; } .page p { color: #4b5563; line-height: 1.6; }
72	  .page .hint { color: #9aa1ab; font-size: 13px; margin-top: 20px; }
