84	<main>
85	  <div class="searchrow">
86	    <span class="mag">⌕</span>
87	    <input id="searchInput" type="text" placeholder="Search everything you saved…" autocomplete="off">
88	  </div>
89	  <div class="labelbar" id="labelbar"></div>
90	  <p class="count" id="count"></p>
91	  <div id="list"></div>
92	</main>
93	
94	<div class="toast" id="toast"></div>
95	<div class="browser" id="browser">
96	  <div class="win">
97	    <div class="chrome"><div class="dots"><span></span><span></span><span></span></div>
98	      <div class="addr" id="addr"></div><div class="closex" id="closeBrowser">✕</div></div>
99	    <div class="page"><h2 id="pageTitle"></h2><p id="pageBody"></p>
100	      <p class="hint">(Simulated: in the real app this is the actual web page opening. Close this to go back.)</p></div>
101	  </div>
102	</div>
103	
104	<script>
105	let bookmarks = [
106	  { id:1, title:"The Sourdough Starter Guide for Beginners", url:"https://kitchenlab.example/sourdough-starter", desc:"How to make and maintain a wild-yeast starter. Covers feeding schedules, the float test, and troubleshooting a starter that won't rise.", img:"https://picsum.photos/seed/bread/216/152", tags:["cooking"] },
107	  { id:2, title:"Understanding CSS Grid Layout", url:"https://webnotes.example/css-grid-deep-dive", desc:"A visual walkthrough of grid-template-areas, fractional units, and building a responsive photo gallery without media queries.", img:"https://picsum.photos/seed/grid/216/152", tags:["web dev","read later"] },
108	  { id:3, title:"Why We Sleep — key takeaways", url:"https://readingnook.example/why-we-sleep-notes", desc:"Notes on Matthew Walker's book. The role of deep sleep in memory, caffeine's half-life, and the danger of chronic sleep debt.", img:"https://picsum.photos/seed/sleep/216/152", tags:["health","read later"] },
109	  { id:4, title:"12 Hidden Gems in Lisbon", url:"https://travelmore.example/lisbon-hidden-gems", desc:"Neighbourhood viewpoints, a family-run tram cafe, and the best pastel de nata away from the tourist crowds.", img:"https://picsum.photos/seed/lisbon/216/152", tags:["travel"] },
110	  { id:5, title:"A Practical Guide to Index Funds", url:"https://moneywise.example/index-funds-101", desc:"What an expense ratio really costs you over 30 years, dollar-cost averaging, and why most active funds underperform.", img:"https://picsum.photos/seed/money/216/152", tags:["finance"] },
111	];
112	
113	const canned = { "https://kitchenlab.example/no-knead-bread": { title:"No-Knead Bread in a Dutch Oven", desc:"A four-ingredient loaf with a crackly crust and open crumb. Long overnight rise, no kneading, baked in a covered pot.", img:"https://picsum.photos/seed/dutchoven/216/152" } };
114	function autoCapture(url){ if(canned[url]) return canned[url]; let host="the page"; try{host=new URL(url).hostname.replace(/^www\./,'');}catch(e){} const seed=encodeURIComponent(url).slice(-12)||"link"; return { title:"Saved page from "+host, desc:"We grabbed this automatically from "+host+". You didn't have to type any of it in.", img:"https://picsum.photos/seed/"+seed+"/216/152" }; }
115	function normUrl(u){ let s=u.trim().toLowerCase(); s=s.replace(/\/+$/,''); s=s.replace(/^https?:\/\//,''); s=s.replace(/^www\./,''); return s; }
116	
117	const listEl=document.getElementById('list'), countEl=document.getElementById('count'),
118	      searchEl=document.getElementById('searchInput'), labelbarEl=document.getElementById('labelbar');
119	let lastNewId=null, editingId=null, flashId=null, activeLabel=null;
120	let draftTags=[]; // tags being edited in the open editor
121	
122	function esc(s){ return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
123	function highlight(text,q){ const safe=esc(text); if(!q) return safe; const re=new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'); return safe.replace(re,'<mark>$1</mark>'); }
124	function allLabels(){ const s=new Set(); bookmarks.forEach(b=>b.tags.forEach(t=>s.add(t))); return [...s].sort(); }
125	
126	function renderLabelbar(){
127	  const labels=allLabels();
128	  let html=`<span class="lead">Labels:</span>`;
129	  html+=`<span class="pill all ${activeLabel===null?'active':''}" data-label="__all">All</span>`;
130	  html+=labels.map(l=>`<span class="pill ${activeLabel===l?'active':''}" data-label="${esc(l)}">${esc(l)} <span style="opacity:.6">${bookmarks.filter(b=>b.tags.includes(l)).length}</span></span>`).join('');
131	  labelbarEl.innerHTML=html;
132	}
133	
134	function cardHtml(b,q,isNew){
135	  if(b.id===editingId){
136	    const chips=draftTags.map((t,i)=>`<span class="chip">${esc(t)}<button data-act="untag" data-i="${i}">×</button></span>`).join('');
137	    return `
138	    <div class="card ${isNew?'new':''}" data-id="${b.id}">
139	      <img class="thumb" src="${b.img}" alt="">
140	      <div class="body">
141	        ${isNew?'<p class="savenote">Saved — the details below were filled in for you. Fix anything you like, and add your own labels.</p>':''}
142	        <div class="edit-form">
143	          <div class="lbl">Title</div><input class="e-title" type="text" value="${esc(b.title)}">
144	          <div class="lbl">Web address</div><input class="e-url" type="text" value="${esc(b.url)}">
145	          <div class="lbl">Summary</div><textarea class="e-desc">${esc(b.desc)}</textarea>
146	          <div class="lbl">Labels</div>
147	          <div class="chipbox" data-act="focustag">${chips}<input class="e-tag" type="text" placeholder="Type a label, press Enter…" list="labelsuggest"></div>
148	          <div class="hintline">Press Enter or comma to add. These are your own words — group things any way you like.</div>
149	          <div class="edit-actions">
150	            <button class="save" data-act="commit">Save changes</button>
151	            <button class="cancel" data-act="cancel">Cancel</button>
152	            <button class="delete" data-act="delete">Delete</button>
153	          </div>
154	        </div>
155	      </div>
156	    </div>`;
157	  }
158	  const tags=b.tags.map(t=>`<span class="tag ${activeLabel===t?'on':''}" data-act="filter" data-label="${esc(t)}">${esc(t)}</span>`).join('');
159	  return `
160	    <div class="card ${isNew?'new':''} ${b.id===flashId?'flash':''}" data-id="${b.id}">
161	      <img class="thumb clickable" src="${b.img}" alt="" data-act="open">
162	      <button class="edit-btn" data-act="edit">Edit</button>
163	      <div class="body">
164	        <div class="clickable" data-act="open">
165	          <div class="title">${highlight(b.title,q)}</div>
166	          <div class="url">${highlight(b.url,q)}</div>
167	          <div class="desc">${highlight(b.desc,q)}</div>
168	        </div>
169	        <div class="tags">${tags}</div>
170	      </div>
171	    </div>`;
172	}
173	
174	function render(){
175	  renderLabelbar();
176	  const q=searchEl.value.trim(), ql=q.toLowerCase();
177	  let matches=bookmarks.filter(b=> !ql || b.title.toLowerCase().includes(ql)||b.url.toLowerCase().includes(ql)||b.desc.toLowerCase().includes(ql)||b.tags.some(t=>t.toLowerCase().includes(ql)));
178	  if(activeLabel!==null) matches=matches.filter(b=>b.tags.includes(activeLabel));
179	  const scope = activeLabel!==null ? (' labelled “'+esc(activeLabel)+'”') : '';
180	  if(matches.length===0){ countEl.textContent=''; listEl.innerHTML='<div class="empty">Nothing'+(q?' matched “'+esc(q)+'”':'')+scope+'.</div>'; return; }
181	  countEl.textContent=(q||activeLabel!==null)? matches.length+' of '+bookmarks.length+' shown' : bookmarks.length+' saved';
182	  listEl.innerHTML=matches.slice().reverse().map(b=>cardHtml(b,q,b.id===lastNewId)).join('');
183	  const openEd=listEl.querySelector('.e-title'); if(openEd) { /* keep focus natural */ }
184	  flashId=null;
185	}
186	
187	function toast(msg,undo){ const t=document.getElementById('toast'); t.innerHTML=esc(msg)+(undo?' <button id="undoBtn">Undo</button>':''); t.classList.add('show'); clearTimeout(t._timer); t._timer=setTimeout(()=>t.classList.remove('show'), undo?5000:2400); if(undo) document.getElementById('undoBtn').addEventListener('click',undo); }
188	function openPage(b){ document.getElementById('addr').textContent=b.url; document.getElementById('pageTitle').textContent=b.title; document.getElementById('pageBody').textContent=b.desc; document.getElementById('browser').classList.add('show'); }
189	document.getElementById('closeBrowser').addEventListener('click',()=>document.getElementById('browser').classList.remove('show'));
190	
191	document.getElementById('saveBtn').addEventListener('click',()=>{
192	  const url=document.getElementById('urlInput').value.trim(); if(!url) return;
193	  const existing=bookmarks.find(b=>normUrl(b.url)===normUrl(url));
194	  if(existing){ document.getElementById('urlInput').value=''; searchEl.value=''; activeLabel=null; lastNewId=null; editingId=null; flashId=existing.id; render(); const c=listEl.querySelector('[data-id="'+existing.id+'"]'); if(c) c.scrollIntoView({behavior:'smooth',block:'center'}); toast("You already saved this — here it is."); return; }
195	  const cap=autoCapture(url); const id=Date.now();
196	  bookmarks.push({ id, url, title:cap.title, desc:cap.desc, img:cap.img, tags:[] });
197	  lastNewId=id; editingId=id; draftTags=[]; activeLabel=null;
198	  document.getElementById('urlInput').value=''; searchEl.value=''; render(); toast('Saved — title and image grabbed automatically');
199	});
200	document.getElementById('urlInput').addEventListener('keydown',e=>{ if(e.key==='Enter') document.getElementById('saveBtn').click(); });
201	searchEl.addEventListener('input',()=>{ lastNewId=null; editingId=null; render(); });
202	
203	labelbarEl.addEventListener('click',e=>{ const p=e.target.closest('[data-label]'); if(!p) return; const l=p.dataset.label; activeLabel=(l==='__all')?null:(activeLabel===l?null:l); editingId=null; render(); });
204	
205	function addDraftTag(raw){ const t=raw.trim().replace(/,$/,'').trim(); if(t && !draftTags.includes(t)) draftTags.push(t); }
206	
207	listEl.addEventListener('keydown',e=>{
208	  if(e.target.classList.contains('e-tag') && (e.key==='Enter'||e.key===',')){
209	    e.preventDefault(); addDraftTag(e.target.value); e.target.value='';
210	    const card=e.target.closest('.card'); render(); const inp=listEl.querySelector('.e-tag'); if(inp) inp.focus();
211	  }
212	});
213	listEl.addEventListener('click',e=>{
214	  const card=e.target.closest('.card'); if(!card) return;
215	  const id=Number(card.dataset.id); const idx=bookmarks.findIndex(x=>x.id===id); const b=bookmarks[idx];
216	  const act=e.target.closest('[data-act]')?.dataset.act;
217	  if(act==='open'){ openPage(b); }
218	  else if(act==='filter'){ const l=e.target.dataset.label; activeLabel=(activeLabel===l?null:l); editingId=null; render(); }
219	  else if(act==='edit'){ editingId=id; draftTags=[...b.tags]; lastNewId=null; render(); const inp=listEl.querySelector('.e-title'); }
220	  else if(act==='cancel'){ editingId=null; lastNewId=null; render(); }
221	  else if(act==='untag'){ draftTags.splice(Number(e.target.dataset.i),1); render(); const inp=listEl.querySelector('.e-tag'); if(inp) inp.focus(); }
222	  else if(act==='focustag'){ const inp=card.querySelector('.e-tag'); if(inp && e.target.classList.contains('chipbox')) inp.focus(); }
223	  else if(act==='commit'){
224	    const pend=card.querySelector('.e-tag').value; addDraftTag(pend);
225	    b.title=card.querySelector('.e-title').value.trim()||b.title;
226	    b.url=card.querySelector('.e-url').value.trim()||b.url;
227	    b.desc=card.querySelector('.e-desc').value.trim()||b.desc;
228	    b.tags=[...draftTags];
229	    editingId=null; lastNewId=null; flashId=id; render(); toast('Updated');
230	  }
231	  else if(act==='delete'){ const removed=bookmarks.splice(idx,1)[0]; editingId=null; lastNewId=null; render();
232	    toast('Deleted “'+removed.title+'”', ()=>{ bookmarks.splice(Math.min(idx,bookmarks.length),0,removed); flashId=removed.id; render(); document.getElementById('toast').classList.remove('show'); }); }
233	});
234	
235	render();
236	</script>
237	<datalist id="labelsuggest"></datalist>
238	<script>
239	  // keep suggestions fresh
240	  const dl=document.getElementById('labelsuggest');
241	  const refresh=()=>{ const s=new Set(); bookmarks.forEach(b=>b.tags.forEach(t=>s.add(t))); dl.innerHTML=[...s].sort().map(t=>`<option value="${t.replace(/"/g,'&quot;')}">`).join(''); };
242	  const obs=new MutationObserver(refresh); obs.observe(document.getElementById('list'),{childList:true,subtree:true}); refresh();
243	</script>
244	</body>
