68	  .edit-actions .save { background: #2f6fed; color: #fff; border: none; border-radius: 7px; padding: 7px 16px; font-weight: 600; cursor: pointer; }
69	  .edit-actions .cancel { background: #fff; color: #4b5563; border: 1px solid #cfd3d8; border-radius: 7px; padding: 7px 16px; cursor: pointer; }
70	  .edit-actions .delete { margin-left: auto; background: #fff; color: #c0392b; border: 1px solid #e6c3bd; border-radius: 7px; padding: 7px 16px; cursor: pointer; }
71	  .edit-actions .delete:hover { background: #fdeeec; }
72	  .savenote { font-size: 12.5px; color: #2f6fed; margin: 0 0 8px; }
73	  .empty { text-align: center; color: #9aa1ab; padding: 50px 0; font-size: 15px; }
74	  .toast { position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); background: #1a1a2e; color: #fff; padding: 12px 18px; border-radius: 10px; font-size: 14px; opacity: 0; pointer-events: none; transition: opacity .2s; z-index: 50; display: flex; align-items: center; gap: 14px; }
75	  .toast.show { opacity: 1; pointer-events: auto; }
76	  .toast button { background: transparent; color: #ffd54a; border: none; font-weight: 700; cursor: pointer; font-size: 14px; }
77	  .browser { position: fixed; inset: 0; background: rgba(0,0,0,.45); z-index: 40; display: none; align-items: flex-start; justify-content: center; padding: 40px 20px; }
78	  .browser.show { display: flex; }
79	  .win { background: #fff; width: 100%; max-width: 760px; border-radius: 12px; overflow: hidden; box-shadow: 0 20px 60px rgba(0,0,0,.35); }
80	  .chrome { display: flex; align-items: center; gap: 10px; background: #ececf0; padding: 10px 14px; border-bottom: 1px solid #dcdee3; }
81	  .dots { display: flex; gap: 6px; } .dots span { width: 11px; height: 11px; border-radius: 50%; background: #c9ccd2; }
82	  .addr { flex: 1; background: #fff; border-radius: 7px; padding: 6px 12px; font-size: 12.5px; color: #4b5563; border: 1px solid #dcdee3; }
83	  .closex { cursor: pointer; color: #6b7280; font-size: 18px; padding: 0 4px; }
84	  .page { padding: 34px 40px 46px; } .page h2 { margin: 0 0 10px; } .page p { color: #4b5563; line-height: 1.6; }
85	  .page .hint { color: #9aa1ab; font-size: 13px; margin-top: 20px; }
86	</style>
87	</head>
88	<body>
89	<header>
90	  <h1>My Bookmarks</h1>
91	  <div class="savebar">
92	    <input id="urlInput" type="text" placeholder="Paste a link to save…" autocomplete="off">
93	    <button id="saveBtn">Save</button>
94	  </div>
95	</header>
96	
97	<main>
98	  <div class="searchrow">
99	    <span class="mag">⌕</span>
100	    <input id="searchInput" type="text" placeholder="Search everything you saved…" autocomplete="off">
101	  </div>
102	  <div class="views" id="views"></div>
103	  <div class="labelbar" id="labelbar"></div>
104	  <p class="count" id="count"></p>
105	  <div id="list"></div>
106	</main>
107	
108	<div class="toast" id="toast"></div>
109	<div class="browser" id="browser">
110	  <div class="win">
111	    <div class="chrome"><div class="dots"><span></span><span></span><span></span></div>
112	      <div class="addr" id="addr"></div><div class="closex" id="closeBrowser">✕</div></div>
113	    <div class="page"><h2 id="pageTitle"></h2><p id="pageBody"></p>
114	      <p class="hint">(Simulated: in the real app this is the actual web page opening. Close this to go back.)</p></div>
115	  </div>
116	</div>
117	
118	<script>
119	let bookmarks = [
120	  { id:1, title:"The Sourdough Starter Guide for Beginners", url:"https://kitchenlab.example/sourdough-starter", desc:"How to make and maintain a wild-yeast starter. Covers feeding schedules, the float test, and troubleshooting a starter that won't rise.", img:"https://picsum.photos/seed/bread/216/152", tags:["cooking"], unread:false },
121	  { id:2, title:"Understanding CSS Grid Layout", url:"https://webnotes.example/css-grid-deep-dive", desc:"A visual walkthrough of grid-template-areas, fractional units, and building a responsive photo gallery without media queries.", img:"https://picsum.photos/seed/grid/216/152", tags:["web dev"], unread:true },
122	  { id:3, title:"Why We Sleep — key takeaways", url:"https://readingnook.example/why-we-sleep-notes", desc:"Notes on Matthew Walker's book. The role of deep sleep in memory, caffeine's half-life, and the danger of chronic sleep debt.", img:"https://picsum.photos/seed/sleep/216/152", tags:["health"], unread:true },
123	  { id:4, title:"12 Hidden Gems in Lisbon", url:"https://travelmore.example/lisbon-hidden-gems", desc:"Neighbourhood viewpoints, a family-run tram cafe, and the best pastel de nata away from the tourist crowds.", img:"https://picsum.photos/seed/lisbon/216/152", tags:["travel"], unread:false },
124	  { id:5, title:"A Practical Guide to Index Funds", url:"https://moneywise.example/index-funds-101", desc:"What an expense ratio really costs you over 30 years, dollar-cost averaging, and why most active funds underperform.", img:"https://picsum.photos/seed/money/216/152", tags:["finance"], unread:false },
125	];
126	
127	const canned = { "https://kitchenlab.example/no-knead-bread": { title:"No-Knead Bread in a Dutch Oven", desc:"A four-ingredient loaf with a crackly crust and open crumb. Long overnight rise, no kneading, baked in a covered pot.", img:"https://picsum.photos/seed/dutchoven/216/152" } };
128	function autoCapture(url){ if(canned[url]) return canned[url]; let host="the page"; try{host=new URL(url).hostname.replace(/^www\./,'');}catch(e){} const seed=encodeURIComponent(url).slice(-12)||"link"; return { title:"Saved page from "+host, desc:"We grabbed this automatically from "+host+". You didn't have to type any of it in.", img:"https://picsum.photos/seed/"+seed+"/216/152" }; }
129	function normUrl(u){ let s=u.trim().toLowerCase(); s=s.replace(/\/+$/,''); s=s.replace(/^https?:\/\//,''); s=s.replace(/^www\./,''); return s; }
130	
131	const listEl=document.getElementById('list'), countEl=document.getElementById('count'),
132	      searchEl=document.getElementById('searchInput'), labelbarEl=document.getElementById('labelbar'),
133	      viewsEl=document.getElementById('views');
134	let lastNewId=null, editingId=null, flashId=null, activeLabel=null, view='all'; // view: 'all' | 'toread'
135	let draftTags=[];
136	
137	function esc(s){ return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
138	function highlight(text,q){ const safe=esc(text); if(!q) return safe; const re=new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'); return safe.replace(re,'<mark>$1</mark>'); }
139	function allLabels(){ const s=new Set(); bookmarks.forEach(b=>b.tags.forEach(t=>s.add(t))); return [...s].sort(); }
140	function toReadCount(){ return bookmarks.filter(b=>b.unread).length; }
141	
142	function renderViews(){
143	  viewsEl.innerHTML =
144	    `<span class="view ${view==='all'?'active':''}" data-view="all">All bookmarks <span class="n">${bookmarks.length}</span></span>`+
145	    `<span class="view toread ${view==='toread'?'active':''}" data-view="toread">📖 To read <span class="n">${toReadCount()}</span></span>`;
146	}
147	function renderLabelbar(){
148	  const labels=allLabels();
149	  let html=`<span class="lead">Labels:</span>`;
150	  html+=`<span class="pill ${activeLabel===null?'active':''}" data-label="__all">All</span>`;
151	  html+=labels.map(l=>`<span class="pill ${activeLabel===l?'active':''}" data-label="${esc(l)}">${esc(l)} <span style="opacity:.6">${bookmarks.filter(b=>b.tags.includes(l)).length}</span></span>`).join('');
152	  labelbarEl.innerHTML=html;
153	}
154	
155	function cardHtml(b,q,isNew){
156	  if(b.id===editingId){
157	    const chips=draftTags.map((t,i)=>`<span class="chip">${esc(t)}<button data-act="untag" data-i="${i}">×</button></span>`).join('');
158	    return `
159	    <div class="card ${isNew?'new':''} ${b.unread?'toread':''}" data-id="${b.id}">
160	      <img class="thumb" src="${b.img}" alt="">
161	      <div class="body">
162	        ${isNew?'<p class="savenote">Saved — the details below were filled in for you. Fix anything you like, and add your own labels.</p>':''}
163	        <div class="edit-form">
164	          <div class="lbl">Title</div><input class="e-title" type="text" value="${esc(b.title)}">
165	          <div class="lbl">Web address</div><input class="e-url" type="text" value="${esc(b.url)}">
166	          <div class="lbl">Summary</div><textarea class="e-desc">${esc(b.desc)}</textarea>
167	          <div class="lbl">Labels</div>
168	          <div class="chipbox" data-act="focustag">${chips}<input class="e-tag" type="text" placeholder="Type a label, press Enter…" list="labelsuggest"></div>
169	          <div class="hintline">Press Enter or comma to add. Your own words — group things any way you like.</div>
170	          <div class="edit-actions">
171	            <button class="save" data-act="commit">Save changes</button>
172	            <button class="cancel" data-act="cancel">Cancel</button>
173	            <button class="delete" data-act="delete">Delete</button>
174	          </div>
175	        </div>
176	      </div>
177	    </div>`;
178	  }
179	  const tags=b.tags.map(t=>`<span class="tag ${activeLabel===t?'on':''}" data-act="filter" data-label="${esc(t)}">${esc(t)}</span>`).join('');
180	  const statusBtn = b.unread
181	    ? `<button class="tbtn markread" data-act="markread">✓ Mark as read</button>`
182	    : `<button class="tbtn toread" data-act="toread">📖 To read</button>`;
183	  return `
184	    <div class="card ${isNew?'new':''} ${b.unread?'toread':''} ${b.id===flashId?'flash':''}" data-id="${b.id}">
185	      <img class="thumb clickable" src="${b.img}" alt="" data-act="open">
186	      <div class="cardtools">${statusBtn}<button class="tbtn" data-act="edit">Edit</button></div>
187	      <div class="body">
188	        <div class="clickable" data-act="open">
189	          <div class="titlerow">${b.unread?'<span class="badge">📖 To read</span>':''}<div class="title">${highlight(b.title,q)}</div></div>
190	          <div class="url">${highlight(b.url,q)}</div>
191	          <div class="desc">${highlight(b.desc,q)}</div>
192	        </div>
193	        <div class="tags">${tags}</div>
194	      </div>
195	    </div>`;
196	}
197	
198	function render(){
199	  renderViews(); renderLabelbar();
200	  const q=searchEl.value.trim(), ql=q.toLowerCase();
201	  let matches=bookmarks.filter(b=> !ql || b.title.toLowerCase().includes(ql)||b.url.toLowerCase().includes(ql)||b.desc.toLowerCase().includes(ql)||b.tags.some(t=>t.toLowerCase().includes(ql)));
202	  if(view==='toread') matches=matches.filter(b=>b.unread);
203	  if(activeLabel!==null) matches=matches.filter(b=>b.tags.includes(activeLabel));
204	  if(matches.length===0){
205	    countEl.textContent='';
206	    const where = view==='toread' ? 'Your to-read pile is empty — nothing left to get to. 🎉' : 'Nothing to show here.';
207	    listEl.innerHTML='<div class="empty">'+where+'</div>'; return;
208	  }
209	  countEl.textContent = (view==='toread') ? matches.length+' to read'
210	    : ((q||activeLabel!==null)? matches.length+' of '+bookmarks.length+' shown' : bookmarks.length+' saved');
211	  listEl.innerHTML=matches.slice().reverse().map(b=>cardHtml(b,q,b.id===lastNewId)).join('');
212	  flashId=null;
213	}
214	
215	function toast(msg,undo){ const t=document.getElementById('toast'); t.innerHTML=esc(msg)+(undo?' <button id="undoBtn">Undo</button>':''); t.classList.add('show'); clearTimeout(t._timer); t._timer=setTimeout(()=>t.classList.remove('show'), undo?5000:2600); if(undo) document.getElementById('undoBtn').addEventListener('click',undo); }
216	function openPage(b){ document.getElementById('addr').textContent=b.url; document.getElementById('pageTitle').textContent=b.title; document.getElementById('pageBody').textContent=b.desc; document.getElementById('browser').classList.add('show'); }
217	document.getElementById('closeBrowser').addEventListener('click',()=>document.getElementById('browser').classList.remove('show'));
218	
219	document.getElementById('saveBtn').addEventListener('click',()=>{
220	  const url=document.getElementById('urlInput').value.trim(); if(!url) return;
221	  const existing=bookmarks.find(b=>normUrl(b.url)===normUrl(url));
222	  if(existing){ document.getElementById('urlInput').value=''; searchEl.value=''; activeLabel=null; view='all'; lastNewId=null; editingId=null; flashId=existing.id; render(); const c=listEl.querySelector('[data-id="'+existing.id+'"]'); if(c) c.scrollIntoView({behavior:'smooth',block:'center'}); toast("You already saved this — here it is."); return; }
223	  const cap=autoCapture(url); const id=Date.now();
224	  bookmarks.push({ id, url, title:cap.title, desc:cap.desc, img:cap.img, tags:[], unread:false });
225	  lastNewId=id; editingId=id; draftTags=[]; activeLabel=null; view='all';
226	  document.getElementById('urlInput').value=''; searchEl.value=''; render(); toast('Saved — title and image grabbed automatically');
227	});
228	document.getElementById('urlInput').addEventListener('keydown',e=>{ if(e.key==='Enter') document.getElementById('saveBtn').click(); });
229	searchEl.addEventListener('input',()=>{ lastNewId=null; editingId=null; render(); });
230	
231	viewsEl.addEventListener('click',e=>{ const v=e.target.closest('[data-view]'); if(!v) return; view=v.dataset.view; editingId=null; render(); });
232	labelbarEl.addEventListener('click',e=>{ const p=e.target.closest('[data-label]'); if(!p) return; const l=p.dataset.label; activeLabel=(l==='__all')?null:(activeLabel===l?null:l); editingId=null; render(); });
233	
234	function addDraftTag(raw){ const t=raw.trim().replace(/,$/,'').trim(); if(t && !draftTags.includes(t)) draftTags.push(t); }
235	listEl.addEventListener('keydown',e=>{ if(e.target.classList.contains('e-tag') && (e.key==='Enter'||e.key===',')){ e.preventDefault(); addDraftTag(e.target.value); e.target.value=''; render(); const inp=listEl.querySelector('.e-tag'); if(inp) inp.focus(); } });
236	
237	listEl.addEventListener('click',e=>{
238	  const card=e.target.closest('.card'); if(!card) return;
239	  const id=Number(card.dataset.id); const idx=bookmarks.findIndex(x=>x.id===id); const b=bookmarks[idx];
240	  const act=e.target.closest('[data-act]')?.dataset.act;
241	  if(act==='open'){ openPage(b); }
242	  else if(act==='filter'){ const l=e.target.dataset.label; activeLabel=(activeLabel===l?null:l); editingId=null; render(); }
243	  else if(act==='edit'){ editingId=id; draftTags=[...b.tags]; lastNewId=null; render(); }
244	  else if(act==='cancel'){ editingId=null; lastNewId=null; render(); }
245	  else if(act==='untag'){ draftTags.splice(Number(e.target.dataset.i),1); render(); const inp=listEl.querySelector('.e-tag'); if(inp) inp.focus(); }
246	  else if(act==='focustag'){ const inp=card.querySelector('.e-tag'); if(inp && e.target.classList.contains('chipbox')) inp.focus(); }
247	  else if(act==='toread'){ b.unread=true; flashId=id; render(); toast('Added to your to-read pile'); }
248	  else if(act==='markread'){
249	    b.unread=false;
250	    if(view==='toread'){ card.classList.add('leaving'); setTimeout(render, 320); }
251	    else { flashId=id; render(); }
252	    toast('Nice — checked off as read', ()=>{ b.unread=true; render(); document.getElementById('toast').classList.remove('show'); });
253	  }
254	  else if(act==='commit'){
255	    const pend=card.querySelector('.e-tag').value; addDraftTag(pend);
256	    b.title=card.querySelector('.e-title').value.trim()||b.title;
257	    b.url=card.querySelector('.e-url').value.trim()||b.url;
258	    b.desc=card.querySelector('.e-desc').value.trim()||b.desc;
259	    b.tags=[...draftTags];
260	    editingId=null; lastNewId=null; flashId=id; render(); toast('Updated');
261	  }
262	  else if(act==='delete'){ const removed=bookmarks.splice(idx,1)[0]; editingId=null; lastNewId=null; render();
263	    toast('Deleted “'+removed.title+'”', ()=>{ bookmarks.splice(Math.min(idx,bookmarks.length),0,removed); flashId=removed.id; render(); document.getElementById('toast').classList.remove('show'); }); }
264	});
265	
266	render();
267	</script>
268	<datalist id="labelsuggest"></datalist>
269	<script>
270	  const dl=document.getElementById('labelsuggest');
271	  const refresh=()=>{ const s=new Set(); bookmarks.forEach(b=>b.tags.forEach(t=>s.add(t))); dl.innerHTML=[...s].sort().map(t=>`<option value="${t.replace(/"/g,'&quot;')}">`).join(''); };
272	  const obs=new MutationObserver(refresh); obs.observe(document.getElementById('list'),{childList:true,subtree:true}); refresh();
273	</script>
274	</body>
