57	  .cardtools { position: absolute; top: 12px; right: 12px; display: flex; gap: 6px; }
58	  .tbtn { font-size: 12.5px; color: #6b7280; background: #f4f5f7; border: 1px solid #e3e5e8; border-radius: 7px; padding: 5px 10px; cursor: pointer; }
59	  .tbtn:hover { background: #e9ebef; }
60	  .tbtn.toread { color: #8a6d0b; border-color: #ecd98f; background: #fdf7e3; }
