64	  .edit-form input, .edit-form textarea { width: 100%; font-size: 14px; padding: 8px 10px; margin-bottom: 8px; border: 1px solid #cfd3d8; border-radius: 7px; font-family: inherit; }
65	  .edit-form .lbl { font-size: 11.5px; font-weight: 600; color: #6b7280; text-transform: uppercase; letter-spacing: .04em; margin-bottom: 3px; }
66	  .edit-form textarea { min-height: 62px; resize: vertical; }
67	  .chipbox { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; border: 1px solid #cfd3d8; border-radius: 7px; padding: 6px 8px; margin-bottom: 8px; }
68	  .chip { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; padding: 3px 4px 3px 10px; border-radius: 999px; background: #d9e5ff; color: #1c4fbf; }
69	  .chip button { border: none; background: transparent; color: #1c4fbf; cursor: pointer; font-size: 13px; line-height: 1; padding: 0 3px; }
70	  .chipbox input { border: none; margin: 0; padding: 4px; flex: 1; min-width: 120px; font-size: 13px; } .chipbox input:focus { outline: none; }
71	  .hintline { font-size: 11.5px; color: #9aa1ab; margin: -4px 0 8px; }
72	  .edit-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
73	  .edit-actions .save { background: #2f6fed; color: #fff; border: none; border-radius: 7px; padding: 7px 16px; font-weight: 600; cursor: pointer; }
74	  .edit-actions .cancel { background: #fff; color: #4b5563; border: 1px solid #cfd3d8; border-radius: 7px; padding: 7px 16px; cursor: pointer; }
75	  .edit-actions .delete { margin-left: auto; background: #fff; color: #c0392b; border: 1px solid #e6c3bd; border-radius: 7px; padding: 7px 16px; cursor: pointer; } .edit-actions .delete:hover { background: #fdeeec; }
76	  .savenote { font-size: 12.5px; color: #2f6fed; margin: 0 0 8px; }
77	  .empty { text-align: center; color: #9aa1ab; padding: 50px 0; font-size: 15px; }
78	  .toast { position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); background: #1a1a2e; color: #fff; padding: 12px 18px; border-radius: 10px; font-size: 14px; opacity: 0; pointer-events: none; transition: opacity .2s; z-index: 50; display: flex; align-items: center; gap: 14px; }
79	  .toast.show { opacity: 1; pointer-events: auto; }
80	  .toast button { background: transparent; color: #ffd54a; border: none; font-weight: 700; cursor: pointer; font-size: 14px; }
81	  .browser { position: fixed; inset: 0; background: rgba(0,0,0,.45); z-index: 40; display: none; align-items: flex-start; justify-content: center; padding: 40px 20px; }
82	  .browser.show { display: flex; }
83	  .win { background: #fff; width: 100%; max-width: 760px; border-radius: 12px; overflow: hidden; box-shadow: 0 20px 60px rgba(0,0,0,.35); }
84	  .chrome { display: flex; align-items: center; gap: 10px; background: #ececf0; padding: 10px 14px; border-bottom: 1px solid #dcdee3; }
85	  .dots { display: flex; gap: 6px; } .dots span { width: 11px; height: 11px; border-radius: 50%; background: #c9ccd2; }
86	  .addr { flex: 1; background: #fff; border-radius: 7px; padding: 6px 12px; font-size: 12.5px; color: #4b5563; border: 1px solid #dcdee3; }
87	  .closex { cursor: pointer; color: #6b7280; font-size: 18px; padding: 0 4px; }
88	  .page { padding: 34px 40px 46px; } .page h2 { margin: 0 0 10px; } .page p { color: #4b5563; line-height: 1.6; }
89	  .page .hint { color: #9aa1ab; font-size: 13px; margin-top: 20px; }
