92	<body>
93	<header>
94	  <h1>My Bookmarks</h1>
95	  <div class="savebar">
96	    <input class="url" id="urlInput" type="text" placeholder="Paste a link to save…" autocomplete="off">
97	    <label class="toread-toggle"><input type="checkbox" id="saveToRead"> 📖 To read</label>
98	    <button class="save" id="saveBtn">Save</button>
99	  </div>
100	</header>
101	
102	<main>
103	  <div class="searchrow">
104	    <span class="mag">⌕</span>
105	    <input id="searchInput" type="text" placeholder="Search everything you saved…" autocomplete="off">
106	  </div>
107	  <div class="views" id="views"></div>
108	  <div class="labelbar" id="labelbar"></div>
109	  <div id="archnote"></div>
110	  <p class="count" id="count"></p>
111	  <div id="list"></div>
112	</main>
113	
114	<div class="toast" id="toast"></div>
115	<div class="browser" id="browser">
116	  <div class="win">
117	    <div class="chrome"><div class="dots"><span></span><span></span><span></span></div>
118	      <div class="addr" id="addr"></div><div class="closex" id="closeBrowser">✕</div></div>
119	    <div class="page"><h2 id="pageTitle"></h2><p id="pageBody"></p>
120	      <p class="hint">(Simulated: in the real app this is the actual web page opening. Close this to go back.)</p></div>
121	  </div>
122	</div>
123	
124	<script>
125	let bookmarks = [
126	  { id:1, title:"The Sourdough Starter Guide for Beginners", url:"https://kitchenlab.example/sourdough-starter", desc:"How to make and maintain a wild-yeast starter. Covers feeding schedules, the float test, and troubleshooting a starter that won't rise.", img:"https://picsum.photos/seed/bread/216/152", tags:["cooking"], unread:false, archived:false },
127	  { id:2, title:"Understanding CSS Grid Layout", url:"https://webnotes.example/css-grid-deep-dive", desc:"A visual walkthrough of grid-template-areas, fractional units, and building a responsive photo gallery without media queries.", img:"https://picsum.photos/seed/grid/216/152", tags:["web dev"], unread:true, archived:false },
128	  { id:3, title:"Why We Sleep — key takeaways", url:"https://readingnook.example/why-we-sleep-notes", desc:"Notes on Matthew Walker's book. The role of deep sleep in memory, caffeine's half-life, and the danger of chronic sleep debt.", img:"https://picsum.photos/seed/sleep/216/152", tags:["health"], unread:true, archived:false },
129	  { id:4, title:"12 Hidden Gems in Lisbon", url:"https://travelmore.example/lisbon-hidden-gems", desc:"Neighbourhood viewpoints, a family-run tram cafe, and the best pastel de nata away from the tourist crowds.", img:"https://picsum.photos/seed/lisbon/216/152", tags:["travel"], unread:false, archived:true },
130	  { id:5, title:"A Practical Guide to Index Funds", url:"https://moneywise.example/index-funds-101", desc:"What an expense ratio really costs you over 30 years, dollar-cost averaging, and why most active funds underperform.", img:"https://picsum.photos/seed/money/216/152", tags:["finance"], unread:false, archived:false },
131	];
132	
133	const canned = { "https://kitchenlab.example/no-knead-bread": { title:"No-Knead Bread in a Dutch Oven", desc:"A four-ingredient loaf with a crackly crust and open crumb. Long overnight rise, no kneading, baked in a covered pot.", img:"https://picsum.photos/seed/dutchoven/216/152" } };
134	function autoCapture(url){ if(canned[url]) return canned[url]; let host="the page"; try{host=new URL(url).hostname.replace(/^www\./,'');}catch(e){} const seed=encodeURIComponent(url).slice(-12)||"link"; return { title:"Saved page from "+host, desc:"We grabbed this automatically from "+host+". You didn't have to type any of it in.", img:"https://picsum.photos/seed/"+seed+"/216/152" }; }
135	function normUrl(u){ let s=u.trim().toLowerCase(); s=s.replace(/\/+$/,''); s=s.replace(/^https?:\/\//,''); s=s.replace(/^www\./,''); return s; }
136	
137	const listEl=document.getElementById('list'), countEl=document.getElementById('count'),
138	      searchEl=document.getElementById('searchInput'), labelbarEl=document.getElementById('labelbar'),
139	      viewsEl=document.getElementById('views'), archnoteEl=document.getElementById('archnote');
140	let lastNewId=null, editingId=null, flashId=null, activeLabel=null, view='all';
141	let draftTags=[];
142	
143	function esc(s){ return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
144	function highlight(text,q){ const safe=esc(text); if(!q) return safe; const re=new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'); return safe.replace(re,'<mark>$1</mark>'); }
145	const active = () => bookmarks.filter(b=>!b.archived);
146	function allLabels(){ const s=new Set(); active().forEach(b=>b.tags.forEach(t=>s.add(t))); return [...s].sort(); }
147	function toReadCount(){ return active().filter(b=>b.unread).length; }
148	function archivedCount(){ return bookmarks.filter(b=>b.archived).length; }
149	
150	function renderViews(){
151	  viewsEl.innerHTML =
152	    `<span class="view ${view==='all'?'active':''}" data-view="all">All bookmarks <span class="n">${active().length}</span></span>`+
153	    `<span class="view toread ${view==='toread'?'active':''}" data-view="toread">📖 To read <span class="n">${toReadCount()}</span></span>`+
154	    `<span class="view archived ${view==='archived'?'active':''}" data-view="archived">🗄 Archived <span class="n">${archivedCount()}</span></span>`;
155	}
156	function renderLabelbar(){
157	  if(view==='archived'){ labelbarEl.innerHTML=''; return; }
158	  const labels=allLabels();
159	  let html=`<span class="lead">Labels:</span>`;
160	  html+=`<span class="pill ${activeLabel===null?'active':''}" data-label="__all">All</span>`;
161	  html+=labels.map(l=>`<span class="pill ${activeLabel===l?'active':''}" data-label="${esc(l)}">${esc(l)} <span style="opacity:.6">${active().filter(b=>b.tags.includes(l)).length}</span></span>`).join('');
162	  labelbarEl.innerHTML=html;
163	}
164	
165	function cardHtml(b,q,isNew){
166	  if(b.id===editingId){
167	    const chips=draftTags.map((t,i)=>`<span class="chip">${esc(t)}<button data-act="untag" data-i="${i}">×</button></span>`).join('');
168	    return `
169	    <div class="card ${isNew?'new':''} ${b.unread?'toread':''}" data-id="${b.id}">
170	      <img class="thumb" src="${b.img}" alt="">
171	      <div class="body">
172	        ${isNew?'<p class="savenote">Saved — the details below were filled in for you. Fix anything you like, and add your own labels.</p>':''}
173	        <div class="edit-form">
174	          <div class="lbl">Title</div><input class="e-title" type="text" value="${esc(b.title)}">
175	          <div class="lbl">Web address</div><input class="e-url" type="text" value="${esc(b.url)}">
176	          <div class="lbl">Summary</div><textarea class="e-desc">${esc(b.desc)}</textarea>
177	          <div class="lbl">Labels</div>
178	          <div class="chipbox" data-act="focustag">${chips}<input class="e-tag" type="text" placeholder="Type a label, press Enter…" list="labelsuggest"></div>
179	          <div class="hintline">Press Enter or comma to add. Your own words — group things any way you like.</div>
180	          <div class="edit-actions">
181	            <button class="save" data-act="commit">Save changes</button>
182	            <button class="cancel" data-act="cancel">Cancel</button>
183	            <button class="delete" data-act="delete">Delete forever</button>
184	          </div>
185	        </div>
186	      </div>
187	    </div>`;
188	  }
189	  const tags=b.tags.map(t=>`<span class="tag ${activeLabel===t?'on':''}" data-act="filter" data-label="${esc(t)}">${esc(t)}</span>`).join('');
190	  let tools;
191	  if(b.archived){
192	    tools = `<button class="tbtn restore" data-act="restore">⤺ Restore</button><button class="tbtn" data-act="edit">Edit</button>`;
193	  } else {
194	    const statusBtn = b.unread ? `<button class="tbtn markread" data-act="markread">✓ Mark as read</button>` : `<button class="tbtn toread" data-act="toread">📖 To read</button>`;
195	    tools = `${statusBtn}<button class="tbtn archive" data-act="archive">🗄 Archive</button><button class="tbtn" data-act="edit">Edit</button>`;
196	  }
197	  const badges = (b.unread?'<span class="badge tr">📖 To read</span>':'') + (b.archived?'<span class="badge ar">🗄 Archived</span>':'');
198	  return `
199	    <div class="card ${isNew?'new':''} ${b.unread?'toread':''} ${b.archived?'archived':''} ${b.id===flashId?'flash':''}" data-id="${b.id}">
200	      <img class="thumb clickable" src="${b.img}" alt="" data-act="open">
201	      <div class="cardtools">${tools}</div>
202	      <div class="body">
203	        <div class="clickable" data-act="open">
204	          <div class="titlerow">${badges}<div class="title">${highlight(b.title,q)}</div></div>
205	          <div class="url">${highlight(b.url,q)}</div>
206	          <div class="desc">${highlight(b.desc,q)}</div>
207	        </div>
208	        <div class="tags">${tags}</div>
209	      </div>
210	    </div>`;
211	}
212	
213	function render(){
214	  renderViews(); renderLabelbar();
215	  archnoteEl.innerHTML = (view==='archived')
216	    ? '<div class="archnote">Archived items are tucked away here — kept out of your everyday list and to-read pile, but not deleted. Restore any of them anytime.</div>' : '';
217	  const q=searchEl.value.trim(), ql=q.toLowerCase();
218	  let pool = (view==='archived') ? bookmarks.filter(b=>b.archived) : active();
219	  let matches=pool.filter(b=> !ql || b.title.toLowerCase().includes(ql)||b.url.toLowerCase().includes(ql)||b.desc.toLowerCase().includes(ql)||b.tags.some(t=>t.toLowerCase().includes(ql)));
220	  if(view==='toread') matches=matches.filter(b=>b.unread);
221	  if(view!=='archived' && activeLabel!==null) matches=matches.filter(b=>b.tags.includes(activeLabel));
222	  if(matches.length===0){
223	    countEl.textContent='';
224	    const where = view==='toread' ? 'Your to-read pile is empty — nothing left to get to. 🎉'
225	      : view==='archived' ? 'Nothing archived.' : 'Nothing to show here.';
226	    listEl.innerHTML='<div class="empty">'+where+'</div>'; return;
227	  }
228	  countEl.textContent = view==='toread' ? matches.length+' to read'
229	    : view==='archived' ? matches.length+' archived'
230	    : ((q||activeLabel!==null)? matches.length+' of '+active().length+' shown' : active().length+' saved');
231	  listEl.innerHTML=matches.slice().reverse().map(b=>cardHtml(b,q,b.id===lastNewId)).join('');
232	  flashId=null;
233	}
234	
235	function toast(msg,undo){ const t=document.getElementById('toast'); t.innerHTML=esc(msg)+(undo?' <button id="undoBtn">Undo</button>':''); t.classList.add('show'); clearTimeout(t._timer); t._timer=setTimeout(()=>t.classList.remove('show'), undo?5000:2600); if(undo) document.getElementById('undoBtn').addEventListener('click',undo); }
236	function openPage(b){ document.getElementById('addr').textContent=b.url; document.getElementById('pageTitle').textContent=b.title; document.getElementById('pageBody').textContent=b.desc; document.getElementById('browser').classList.add('show'); }
237	document.getElementById('closeBrowser').addEventListener('click',()=>document.getElementById('browser').classList.remove('show'));
238	
239	document.getElementById('saveBtn').addEventListener('click',()=>{
240	  const url=document.getElementById('urlInput').value.trim(); if(!url) return;
241	  const wantToRead=document.getElementById('saveToRead').checked;
242	  const existing=bookmarks.find(b=>normUrl(b.url)===normUrl(url));
243	  if(existing){ document.getElementById('urlInput').value=''; document.getElementById('saveToRead').checked=false; searchEl.value=''; activeLabel=null; view= existing.archived?'archived':'all'; lastNewId=null; editingId=null; flashId=existing.id; render(); const c=listEl.querySelector('[data-id="'+existing.id+'"]'); if(c) c.scrollIntoView({behavior:'smooth',block:'center'}); toast("You already saved this — here it is."); return; }
244	  const cap=autoCapture(url); const id=Date.now();
245	  bookmarks.push({ id, url, title:cap.title, desc:cap.desc, img:cap.img, tags:[], unread:wantToRead, archived:false });
246	  lastNewId=id; editingId=id; draftTags=[]; activeLabel=null; view='all';
247	  document.getElementById('urlInput').value=''; document.getElementById('saveToRead').checked=false; searchEl.value=''; render();
248	  toast(wantToRead ? 'Saved to your to-read pile — details grabbed automatically' : 'Saved — title and image grabbed automatically');
249	});
250	document.getElementById('urlInput').addEventListener('keydown',e=>{ if(e.key==='Enter') document.getElementById('saveBtn').click(); });
251	searchEl.addEventListener('input',()=>{ lastNewId=null; editingId=null; render(); });
252	
253	viewsEl.addEventListener('click',e=>{ const v=e.target.closest('[data-view]'); if(!v) return; view=v.dataset.view; activeLabel=null; editingId=null; render(); });
254	labelbarEl.addEventListener('click',e=>{ const p=e.target.closest('[data-label]'); if(!p) return; const l=p.dataset.label; activeLabel=(l==='__all')?null:(activeLabel===l?null:l); editingId=null; render(); });
255	
256	function addDraftTag(raw){ const t=raw.trim().replace(/,$/,'').trim(); if(t && !draftTags.includes(t)) draftTags.push(t); }
257	listEl.addEventListener('keydown',e=>{ if(e.target.classList.contains('e-tag') && (e.key==='Enter'||e.key===',')){ e.preventDefault(); addDraftTag(e.target.value); e.target.value=''; render(); const inp=listEl.querySelector('.e-tag'); if(inp) inp.focus(); } });
258	
259	listEl.addEventListener('click',e=>{
260	  const card=e.target.closest('.card'); if(!card) return;
261	  const id=Number(card.dataset.id); const idx=bookmarks.findIndex(x=>x.id===id); const b=bookmarks[idx];
262	  const act=e.target.closest('[data-act]')?.dataset.act;
263	  if(act==='open'){ openPage(b); }
264	  else if(act==='filter'){ const l=e.target.dataset.label; activeLabel=(activeLabel===l?null:l); editingId=null; render(); }
265	  else if(act==='edit'){ editingId=id; draftTags=[...b.tags]; lastNewId=null; render(); }
266	  else if(act==='cancel'){ editingId=null; lastNewId=null; render(); }
267	  else if(act==='untag'){ draftTags.splice(Number(e.target.dataset.i),1); render(); const inp=listEl.querySelector('.e-tag'); if(inp) inp.focus(); }
268	  else if(act==='focustag'){ const inp=card.querySelector('.e-tag'); if(inp && e.target.classList.contains('chipbox')) inp.focus(); }
269	  else if(act==='toread'){ b.unread=true; flashId=id; render(); toast('Added to your to-read pile'); }
270	  else if(act==='markread'){ b.unread=false; if(view==='toread'){ card.classList.add('leaving'); setTimeout(render,320);} else { flashId=id; render(); } toast('Nice — checked off as read', ()=>{ b.unread=true; render(); document.getElementById('toast').classList.remove('show'); }); }
271	  else if(act==='archive'){ b.archived=true; card.classList.add('leaving'); setTimeout(render,320); toast('Tucked away in your archive', ()=>{ b.archived=false; render(); document.getElementById('toast').classList.remove('show'); }); }
272	  else if(act==='restore'){ b.archived=false; card.classList.add('leaving'); setTimeout(render,320); toast('Back in your bookmarks', ()=>{ b.archived=true; render(); document.getElementById('toast').classList.remove('show'); }); }
273	  else if(act==='commit'){
274	    const pend=card.querySelector('.e-tag').value; addDraftTag(pend);
275	    b.title=card.querySelector('.e-title').value.trim()||b.title;
276	    b.url=card.querySelector('.e-url').value.trim()||b.url;
277	    b.desc=card.querySelector('.e-desc').value.trim()||b.desc;
278	    b.tags=[...draftTags];
279	    editingId=null; lastNewId=null; flashId=id; render(); toast('Updated');
280	  }
281	  else if(act==='delete'){ const removed=bookmarks.splice(idx,1)[0]; editingId=null; lastNewId=null; render();
282	    toast('Deleted “'+removed.title+'” for good', ()=>{ bookmarks.splice(Math.min(idx,bookmarks.length),0,removed); flashId=removed.id; render(); document.getElementById('toast').classList.remove('show'); }); }
283	});
284	
285	render();
286	</script>
287	<datalist id="labelsuggest"></datalist>
288	<script>
289	  const dl=document.getElementById('labelsuggest');
290	  const refresh=()=>{ const s=new Set(); bookmarks.forEach(b=>b.tags.forEach(t=>s.add(t))); dl.innerHTML=[...s].sort().map(t=>`<option value="${t.replace(/"/g,'&quot;')}">`).join(''); };
291	  const obs=new MutationObserver(refresh); obs.observe(document.getElementById('list'),{childList:true,subtree:true}); refresh();
292	</script>
293	</body>
