98	<body>
99	<header>
100	  <h1>My Bookmarks</h1>
101	  <div class="savebar">
102	    <input class="url" id="urlInput" type="text" placeholder="Paste a link to save…" autocomplete="off">
103	    <label class="toread-toggle"><input type="checkbox" id="saveToRead"> 📖 To read</label>
