106	  <div class="saveerr" id="saveerr"></div>
107	</header>
108	
109	<main>
110	  <div class="searchrow"><span class="mag">⌕</span><input id="searchInput" type="text" placeholder="Search everything you saved…" autocomplete="off"></div>
111	  <div class="views" id="views"></div>
112	  <div class="labelbar" id="labelbar"></div>
113	  <p class="count" id="count"></p>
114	  <div id="list"></div>
115	</main>
116	
117	<div class="toast" id="toast"></div>
118	<div class="browser" id="browser">
119	  <div class="win">
120	    <div class="chrome"><div class="dots"><span></span><span></span><span></span></div>
121	      <div class="addr" id="addr"></div><div class="closex" id="closeBrowser">✕</div></div>
122	    <div id="pagearea"></div>
123	  </div>
124	</div>
