126	<script>
127	// starts EMPTY to show the first-run experience
128	let bookmarks = [];
129	
130	// simulated capture: some links can't be read; one is a "gone" page for link-rot
131	const canned = {
132	  "https://kitchenlab.example/no-knead-bread": { title:"No-Knead Bread in a Dutch Oven", desc:"A four-ingredient loaf with a crackly crust and open crumb. Long overnight rise, no kneading, baked in a covered pot.", img:"https://picsum.photos/seed/dutchoven/216/152" },
133	  "https://blog.example/great-article": { title:"The Article You Meant to Keep", desc:"A long read on focus and attention in a distracted world.", img:"https://picsum.photos/seed/focus/216/152", gone:true },
134	};
135	const unreadable = new Set(["https://broken.example/unreadable","https://intranet.local/report"]);
136	
137	function looksLikeUrl(raw){
138	  let s=raw.trim(); if(!s || /\s/.test(s)) return null;
139	  if(!/^https?:\/\//i.test(s)) s='https://'+s;
140	  try{ const u=new URL(s); if(!u.hostname.includes('.')) return null; return s; }catch(e){ return null; }
141	}
142	function autoCapture(url){
143	  if(canned[url]) return { ...canned[url], failed:false };
144	  if(unreadable.has(url)) return { failed:true };
145	  let host="the page"; try{host=new URL(url).hostname.replace(/^www\./,'');}catch(e){}
146	  const seed=encodeURIComponent(url).slice(-12)||"link";
147	  return { failed:false, title:"Saved page from "+host, desc:"We grabbed this automatically from "+host+".", img:"https://picsum.photos/seed/"+seed+"/216/152" };
148	}
149	function normUrl(u){ let s=u.trim().toLowerCase(); s=s.replace(/\/+$/,''); s=s.replace(/^https?:\/\//,''); s=s.replace(/^www\./,''); return s; }
150	
151	const listEl=document.getElementById('list'), countEl=document.getElementById('count'),
152	      searchEl=document.getElementById('searchInput'), labelbarEl=document.getElementById('labelbar'),
153	      viewsEl=document.getElementById('views'), errEl=document.getElementById('saveerr');
154	let lastNewId=null, editingId=null, flashId=null, activeLabel=null, view='all', draftTags=[];
155	
156	function esc(s){ return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
157	function highlight(text,q){ const safe=esc(text); if(!q) return safe; const re=new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'); return safe.replace(re,'<mark>$1</mark>'); }
158	const active=()=>bookmarks.filter(b=>!b.archived);
159	function allLabels(){ const s=new Set(); active().forEach(b=>b.tags.forEach(t=>s.add(t))); return [...s].sort(); }
160	
161	function renderViews(){
162	  viewsEl.innerHTML =
163	    `<span class="view ${view==='all'?'active':''}" data-view="all">All bookmarks <span class="n">${active().length}</span></span>`+
164	    `<span class="view toread ${view==='toread'?'active':''}" data-view="toread">📖 To read <span class="n">${active().filter(b=>b.unread).length}</span></span>`+
165	    `<span class="view archived ${view==='archived'?'active':''}" data-view="archived">🗄 Archived <span class="n">${bookmarks.filter(b=>b.archived).length}</span></span>`;
166	}
167	function renderLabelbar(){
168	  if(view==='archived' || active().length===0){ labelbarEl.innerHTML=''; return; }
169	  const labels=allLabels(); let html=`<span class="lead">Labels:</span><span class="pill ${activeLabel===null?'active':''}" data-label="__all">All</span>`;
170	  html+=labels.map(l=>`<span class="pill ${activeLabel===l?'active':''}" data-label="${esc(l)}">${esc(l)}</span>`).join('');
171	  labelbarEl.innerHTML=html;
172	}
173	
174	function thumbHtml(b, cls){
175	  if(b.img) return `<img class="thumb ${cls}" src="${b.img}" alt="" data-act="open">`;
176	  return `<div class="thumb placeholder ${cls}" data-act="open" title="No image">🔗</div>`;
177	}
178	
179	function cardHtml(b,q,isNew){
180	  if(b.id===editingId){
181	    const chips=draftTags.map((t,i)=>`<span class="chip">${esc(t)}<button data-act="untag" data-i="${i}">×</button></span>`).join('');
182	    let note='';
183	    if(isNew && b.captureFailed) note='<p class="savenote warn">Saved, but we couldn\'t read this page automatically. Add a title and summary so you can find it later.</p>';
184	    else if(isNew) note='<p class="savenote ok">Saved — details filled in for you. Fix anything you like, and add your own labels.</p>';
185	    return `
186	    <div class="card ${isNew?'new':''}" data-id="${b.id}">
187	      ${thumbHtml(b,'')}
188	      <div class="body"><div class="edit-form">${note}
189	        <div class="lbl">Title</div><input class="e-title" type="text" value="${esc(b.title)}" placeholder="Give it a title you'll recognise">
190	        <div class="lbl">Web address</div><input class="e-url" type="text" value="${esc(b.url)}">
191	        <button class="refetch" data-act="refetch">↻ Re-fetch info from this link</button>
192	        <div class="refetchhint">Use this if you changed the address to a different page and want fresh title/summary/image.</div>
193	        <div class="lbl">Summary</div><textarea class="e-desc" placeholder="A few words about what this is">${esc(b.desc)}</textarea>
194	        <div class="lbl">Labels</div>
195	        <div class="chipbox" data-act="focustag">${chips}<input class="e-tag" type="text" placeholder="Type a label, press Enter…" list="labelsuggest"></div>
196	        <div class="edit-actions">
197	          <button class="save" data-act="commit">Save changes</button>
198	          <button class="cancel" data-act="cancel">Cancel</button>
199	          <button class="delete" data-act="delete">Delete forever</button>
200	        </div></div></div>
201	    </div>`;
202	  }
203	  const tags=b.tags.map(t=>`<span class="tag" data-act="filter" data-label="${esc(t)}">${esc(t)}</span>`).join('');
204	  const statusBtn = b.unread ? `<button class="tbtn markread" data-act="markread">✓ Mark as read</button>` : `<button class="tbtn toread" data-act="toread">📖 To read</button>`;
205	  const tools = b.archived ? `<button class="tbtn" data-act="restore">⤺ Restore</button><button class="tbtn" data-act="edit">Edit</button>`
206	    : `${statusBtn}<button class="tbtn" data-act="archive">🗄 Archive</button><button class="tbtn" data-act="edit">Edit</button>`;
207	  const needsInfo = b.captureFailed && !b.title;
208	  const badges = (b.unread?'<span class="badge tr">📖 To read</span>':'') + (needsInfo?'<span class="badge ni">needs a title</span>':'');
209	  const titleHtml = b.title ? highlight(b.title,q) : 'Untitled — add a title';
210	  const descHtml = b.desc ? highlight(b.desc,q) : (b.captureFailed ? 'No summary yet — add one so you can find this later.' : '');
211	  return `
212	    <div class="card ${isNew?'new':''} ${b.unread?'toread':''} ${needsInfo?'needsinfo':''} ${b.id===flashId?'flash':''}" data-id="${b.id}">
213	      ${thumbHtml(b,'clickable')}
214	      <div class="cardtools">${tools}</div>
215	      <div class="body">
216	        <div class="clickable" data-act="open">
217	          <div class="titlerow">${badges}<div class="title ${b.title?'':'untitled'}">${titleHtml}</div></div>
218	          <div class="url">${highlight(b.url,q)}</div>
219	          <div class="desc ${b.desc?'':'missing'}">${descHtml}</div>
220	        </div>
221	        <div class="tags">${tags}</div>
222	      </div>
223	    </div>`;
224	}
225	
226	function render(){
227	  renderViews(); renderLabelbar();
228	  const q=searchEl.value.trim(), ql=q.toLowerCase();
229	  // first-run welcome
230	  if(view==='all' && !q && active().length===0){
231	    countEl.textContent='';
232	    listEl.innerHTML=`<div class="welcome"><div class="big">🔖</div><h2>Your bookmarks live here</h2>
233	      <p>Nothing saved yet. When you find something worth keeping, paste its link up top and Save — the title, a picture, and a summary get grabbed for you.</p>
234	      <p>Later, search by anything you remember, or group things with your own labels.</p>
235	      <p class="arrow">↑ Paste your first link to begin.</p></div>`;
236	    return;
237	  }
238	  let pool = (view==='archived') ? bookmarks.filter(b=>b.archived) : active();
239	  let matches=pool.filter(b=> !ql || b.title.toLowerCase().includes(ql)||b.url.toLowerCase().includes(ql)||b.desc.toLowerCase().includes(ql)||b.tags.some(t=>t.toLowerCase().includes(ql)));
240	  if(view==='toread') matches=matches.filter(b=>b.unread);
241	  if(view!=='archived' && activeLabel!==null) matches=matches.filter(b=>b.tags.includes(activeLabel));
242	  if(matches.length===0){
243	    countEl.textContent='';
244	    const where = q ? 'Nothing matched “'+esc(q)+'”.' : view==='toread' ? 'Your to-read pile is empty. 🎉' : view==='archived' ? 'Nothing archived.' : 'Nothing here.';
245	    listEl.innerHTML='<div class="empty">'+where+'</div>'; return;
246	  }
247	  countEl.textContent = q ? matches.length+' of '+active().length+' match' : (view==='all'? active().length+' saved':'');
248	  listEl.innerHTML=matches.slice().reverse().map(b=>cardHtml(b,q,b.id===lastNewId)).join('');
249	  flashId=null;
250	}
251	
252	function toast(msg,undo){ const t=document.getElementById('toast'); t.innerHTML=esc(msg)+(undo?' <button id="undoBtn">Undo</button>':''); t.classList.add('show'); clearTimeout(t._timer); t._timer=setTimeout(()=>t.classList.remove('show'), undo?5000:2600); if(undo) document.getElementById('undoBtn').addEventListener('click',undo); }
253	
254	function openPage(b){
255	  document.getElementById('addr').textContent=b.url;
256	  const area=document.getElementById('pagearea');
257	  if(b.gone){
258	    area.innerHTML=`<div class="page gone"><div class="big">🚫</div><h2>This page is no longer available</h2>
259	      <p>The original page has gone (moved or taken down). But here's the snapshot you saved, so you still know what it was:</p>
260	      <div class="snapshot"><div class="k">Title</div><div>${esc(b.title||'—')}</div>
261	        <div class="k" style="margin-top:10px">Summary</div><div>${esc(b.desc||'—')}</div></div></div>`;
262	  } else {
263	    area.innerHTML=`<div class="page"><h2>${esc(b.title||'(untitled)')}</h2><p>${esc(b.desc||'')}</p>
264	      <p class="refetchhint">(Simulated destination page. Close this to go back.)</p></div>`;
265	  }
266	  document.getElementById('browser').classList.add('show');
267	}
268	document.getElementById('closeBrowser').addEventListener('click',()=>document.getElementById('browser').classList.remove('show'));
269	
270	function clearErr(){ errEl.textContent=''; document.getElementById('urlInput').classList.remove('err'); }
271	document.getElementById('urlInput').addEventListener('input', clearErr);
272	
273	document.getElementById('saveBtn').addEventListener('click',()=>{
274	  const raw=document.getElementById('urlInput').value; const url=looksLikeUrl(raw);
275	  if(!raw.trim()) return;
276	  if(!url){ errEl.textContent="That doesn't look like a web address — check it and try again."; document.getElementById('urlInput').classList.add('err'); return; }
277	  clearErr();
278	  const wantToRead=document.getElementById('saveToRead').checked;
279	  const existing=bookmarks.find(b=>normUrl(b.url)===normUrl(url));
280	  if(existing){ document.getElementById('urlInput').value=''; document.getElementById('saveToRead').checked=false; searchEl.value=''; activeLabel=null; view=existing.archived?'archived':'all'; lastNewId=null; editingId=null; flashId=existing.id; render(); const c=listEl.querySelector('[data-id="'+existing.id+'"]'); if(c) c.scrollIntoView({behavior:'smooth',block:'center'}); toast('You already saved this — here it is.'); return; }
281	  const cap=autoCapture(url); const id=Date.now();
282	  bookmarks.push({ id, url, title:cap.failed?'':cap.title, desc:cap.failed?'':cap.desc, img:cap.failed?null:cap.img, gone:!!cap.gone, tags:[], unread:wantToRead, archived:false, captureFailed:cap.failed });
283	  lastNewId=id; editingId=id; draftTags=[]; activeLabel=null; view='all';
284	  document.getElementById('urlInput').value=''; document.getElementById('saveToRead').checked=false; searchEl.value=''; render();
285	  toast(cap.failed ? "Saved — but we couldn't read this page. Add a title so you can find it." : (wantToRead?'Saved to your to-read pile':'Saved — details grabbed automatically'));
286	});
287	document.getElementById('urlInput').addEventListener('keydown',e=>{ if(e.key==='Enter') document.getElementById('saveBtn').click(); });
288	searchEl.addEventListener('input',()=>{ lastNewId=null; editingId=null; render(); });
289	viewsEl.addEventListener('click',e=>{ const v=e.target.closest('[data-view]'); if(!v) return; view=v.dataset.view; activeLabel=null; editingId=null; render(); });
290	labelbarEl.addEventListener('click',e=>{ const p=e.target.closest('[data-label]'); if(!p) return; const l=p.dataset.label; activeLabel=(l==='__all')?null:(activeLabel===l?null:l); editingId=null; render(); });
