137	<script>
138	let bookmarks = [
139	  { id:1, title:"No-Knead Bread in a Dutch Oven", url:"https://kitchenlab.example/no-knead-bread", desc:"A four-ingredient loaf with a crackly crust and open crumb.", img:"https://picsum.photos/seed/dutchoven/216/152", tags:["cooking"], unread:false, archived:false, gone:false,
140	    copy:"Stir together flour, water, salt, and a pinch of yeast. The slow rise builds an open crumb, and a covered pot traps steam for a thin, crackly crust." },
141	  { id:2, title:"The Sourdough Starter Guide for Beginners", url:"https://kitchenlab.example/sourdough-starter", desc:"Feeding schedules and troubleshooting a sourdough starter.", img:"https://picsum.photos/seed/bread/216/152", tags:["cooking"], unread:true, archived:false, gone:false,
142	    copy:"A healthy sourdough starter is the engine of good bread. Once it doubles you can bake a loaf with a springy crumb and a deeply coloured crust." },
143	  { id:3, title:"Chocolate Lava Cake in 15 Minutes", url:"https://kitchenlab.example/lava-cake", desc:"A quick molten dessert with a gooey centre.", img:"https://picsum.photos/seed/lava/216/152", tags:["cooking","dessert"], unread:false, archived:false, gone:false,
144	    copy:"This dessert bakes just long enough to set the edges while the centre stays molten. No sourdough, no crust — just a warm chocolate pudding." },
145	  { id:4, title:"The Article You Meant to Keep", url:"https://blog.example/great-article", desc:"A long read on focus and attention.", img:"https://picsum.photos/seed/focus/216/152", tags:["read"], unread:true, archived:false, gone:false,
146	    copy:"We treat attention as if it were infinite. Every notification is a small withdrawal, and willpower is barely needed once distractions are out of reach." },
147	  { id:5, title:"Why We Sleep — key takeaways", url:"https://readingnook.example/why-we-sleep", desc:"Notes on sleep, memory, and caffeine.", img:"https://picsum.photos/seed/sleep/216/152", tags:["health","read"], unread:false, archived:false, gone:false,
148	    copy:"Deep sleep consolidates memory. Caffeine has a long half-life that steals from the sleep you need, dulling attention and focus the next day." },
149	  { id:6, title:"12 Hidden Gems in Lisbon", url:"https://travelmore.example/lisbon", desc:"Viewpoints, a tram cafe, and the best pastel de nata.", img:"https://picsum.photos/seed/lisbon/216/152", tags:["travel"], unread:false, archived:true, gone:false,
150	    copy:"Away from the crowds, Lisbon rewards wandering: miradouros at golden hour, a family tram cafe, and custard tarts still warm from the oven." },
151	];
152	const canned = { "https://kitchenlab.example/no-knead-bread": { title:"No-Knead Bread in a Dutch Oven", desc:"A four-ingredient loaf with a crackly crust and open crumb.", img:"https://picsum.photos/seed/dutchoven/216/152", copy:bookmarks[0].copy } };
153	const unreadable=new Set(["https://broken.example/unreadable"]);
154	function looksLikeUrl(raw){ let s=raw.trim(); if(!s||/\s/.test(s)) return null; if(!/^https?:\/\//i.test(s)) s='https://'+s; try{ const u=new URL(s); if(!u.hostname.includes('.')) return null; return s; }catch(e){ return null; } }
155	function autoCapture(url){ if(canned[url]) return {...canned[url], failed:false}; if(unreadable.has(url)) return {failed:true}; let host="the page"; try{host=new URL(url).hostname.replace(/^www\./,'');}catch(e){} const seed=encodeURIComponent(url).slice(-12)||"link"; return { failed:false, title:"Saved page from "+host, desc:"Grabbed automatically from "+host+".", img:"https://picsum.photos/seed/"+seed+"/216/152", copy:"A readable copy of this page was kept when you saved it." }; }
156	function normUrl(u){ let s=u.trim().toLowerCase(); s=s.replace(/\/+$/,''); s=s.replace(/^https?:\/\//,''); s=s.replace(/^www\./,''); return s; }
157	
158	const W={title:100,summary:40,labels:40,url:20,body:10};
159	const EXCLUDE=new Set(['not','without','except']);
160	const listEl=document.getElementById('list'),countEl=document.getElementById('count'),searchEl=document.getElementById('searchInput'),
161	      labelbarEl=document.getElementById('labelbar'),viewsEl=document.getElementById('views'),interpEl=document.getElementById('interp'),
162	      scopeEl=document.getElementById('scope'),errEl=document.getElementById('saveerr');
163	let editingId=null,flashId=null,activeLabel=null,view='all',draftTags=[],currentOpen=null;
164	
165	function esc(s){ return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
166	function hlTerms(text,terms){ let safe=esc(text); terms.forEach(t=>{ if(!t) return; const re=new RegExp('('+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig'); safe=safe.replace(re,'<mark>$1</mark>'); }); return safe; }
167	function fieldsOf(b){ return {title:b.title,summary:b.desc,labels:(b.tags||[]).join(' '),url:b.url,body:b.copy||''}; }
168	const active=()=>bookmarks.filter(b=>!b.archived);
169	function allLabels(){ const s=new Set(); active().forEach(b=>b.tags.forEach(t=>s.add(t))); return [...s].sort(); }
170	
171	function parse(q){ const raw=q.match(/-?"[^"]*"|\S+/g)||[]; const groups=[],negs=[]; let pOr=false,pNeg=false;
172	  for(const r0 of raw){ let r=r0,neg=false,phrase=false; if(r[0]==='-'){neg=true;r=r.slice(1);} if(r[0]==='"'){phrase=true;r=r.replace(/^"|"$/g,'');} const text=r.toLowerCase().trim(); if(!text) continue;
173	    if(!phrase&&!neg){ if(text==='or'&&groups.length){pOr=true;continue;} if(text==='and'){continue;} if(EXCLUDE.has(text)){pNeg=true;continue;} }
174	    if(neg||pNeg){ negs.push({text}); pNeg=false; continue; }
175	    const tok={text,phrase}; if(pOr&&groups.length){ groups[groups.length-1].push(tok); pOr=false; } else groups.push([tok]); }
176	  return {groups,negs}; }
177	function scoreOf(b,p){ const f=fieldsOf(b); const flat=Object.values(f).join(' ').toLowerCase();
178	  for(const n of p.negs){ if(flat.includes(n.text)) return null; }
179	  let total=0; const why=[];
180	  for(const grp of p.groups){ let best=0,bf=null,bt=null; for(const alt of grp){ for(const k in f){ if(f[k].toLowerCase().includes(alt.text)){ if(W[k]>best){best=W[k];bf=k;bt=alt.text;} } } } if(best===0) return null; total+=best; why.push({term:bt,field:bf}); }
181	  return {total,why,strong:why.some(w=>['title','summary','labels'].includes(w.field))}; }
182	function allTerms(p){ const s=new Set(); p.groups.forEach(g=>g.forEach(t=>s.add(t.text))); return [...s]; }
183	function snippetFor(b,terms){ const body=b.copy||'',low=body.toLowerCase(); for(const t of terms){ const i=low.indexOf(t); if(i>=0){ const s=Math.max(0,i-40),e=Math.min(body.length,i+70); return (s>0?'…':'')+body.slice(s,e)+(e<body.length?'…':''); } } return ''; }
184	
185	function renderViews(){ viewsEl.innerHTML=
186	  `<span class="view ${view==='all'?'active':''}" data-view="all">All bookmarks <span class="n">${active().length}</span></span>`+
187	  `<span class="view toread ${view==='toread'?'active':''}" data-view="toread">📖 To read <span class="n">${active().filter(b=>b.unread).length}</span></span>`+
188	  `<span class="view archived ${view==='archived'?'active':''}" data-view="archived">🗄 Archived <span class="n">${bookmarks.filter(b=>b.archived).length}</span></span>`; }
189	function renderLabelbar(){ if(view==='archived'){ labelbarEl.innerHTML=''; return; } const labels=allLabels();
190	  labelbarEl.innerHTML=`<span class="lead">Labels:</span><span class="pill ${activeLabel===null?'active':''}" data-label="__all">All</span>`+
191	    labels.map(l=>`<span class="pill ${activeLabel===l?'active':''}" data-label="${esc(l)}">${esc(l)}</span>`).join(''); }
192	function renderInterp(p){ const chips=[]; p.groups.forEach(g=>{ if(g.length>1) chips.push(`<span class="icap either">either: ${g.map(t=>esc(t.text)).join(' / ')}</span>`); else if(g[0].phrase) chips.push(`<span class="icap phrase">exact phrase: “${esc(g[0].text)}”</span>`); else chips.push(`<span class="icap word">${esc(g[0].text)}</span>`); }); p.negs.forEach(n=>chips.push(`<span class="icap without">without: ${esc(n.text)}</span>`)); const special=p.groups.some(g=>g.length>1||g[0].phrase)||p.negs.length; interpEl.innerHTML=(chips.length&&special)?`<span class="lab">Reading your search as:</span>`+chips.join(''):''; }
193	
194	function scopeText(){ const parts=[]; if(view==='toread') parts.push('your 📖 To read pile'); if(view==='archived') parts.push('your 🗄 Archive'); if(activeLabel) parts.push('label “'+esc(activeLabel)+'”'); return parts; }
195	
196	function cardHtml(b,terms,q,rank){
197	  if(b.id===editingId){ const chips=draftTags.map((t,i)=>`<span class="chip">${esc(t)}<button data-act="untag" data-i="${i}">×</button></span>`).join('');
198	    let note = b.captureFailed&&!b.title?'<p class="savenote warn">Couldn\'t read this page — add a title and summary so you can find it later.</p>':'';
199	    return `<div class="card" data-id="${b.id}">${b.img?`<img class="thumb" src="${b.img}">`:'<div class="thumb placeholder">🔗</div>'}
200	      <div class="body"><div class="edit-form">${note}
201	        <div class="lbl">Title</div><input class="e-title" type="text" value="${esc(b.title)}" placeholder="Give it a title you'll recognise">
202	        <div class="lbl">Web address</div><input class="e-url" type="text" value="${esc(b.url)}">
203	        <button class="refetch" data-act="refetch">↻ Re-fetch info from this link</button>
204	        <div class="lbl">Summary</div><textarea class="e-desc">${esc(b.desc)}</textarea>
205	        <div class="lbl">Labels</div><div class="chipbox" data-act="focustag">${chips}<input class="e-tag" type="text" placeholder="Type a label, press Enter…"></div>
206	        <div class="edit-actions"><button class="save" data-act="commit">Save changes</button><button class="cancel" data-act="cancel">Cancel</button><button class="delete" data-act="delete">Delete forever</button></div>
207	      </div></div></div>`; }
208	  const tags=b.tags.map(t=>`<span class="tag ${activeLabel===t?'on':''}" data-act="filter" data-label="${esc(t)}">${esc(t)}</span>`).join('');
209	  const statusBtn=b.unread?`<button class="tbtn markread" data-act="markread">✓ Mark as read</button>`:`<button class="tbtn toread" data-act="toread">📖 To read</button>`;
210	  const tools=b.archived?`<button class="tbtn restore" data-act="restore">⤺ Restore</button><button class="tbtn" data-act="edit">Edit</button>`:`${statusBtn}<button class="tbtn" data-act="archive">🗄 Archive</button><button class="tbtn" data-act="edit">Edit</button>`;
211	  const badges=(b.unread?'<span class="badge tr">📖 To read</span>':'')+(b.archived?'<span class="badge ar">🗄 Archived</span>':'');
212	  const why=q?(scoreOf(b,parse(q))?.why||[]).map(w=>{const label=w.field==='title'?'in title':w.field==='summary'?'in summary':w.field==='labels'?'in label':w.field==='url'?'in link':'in page text';const cls=['title','summary','labels'].includes(w.field)?'strong':'bodyhit';return `<span class="hit ${cls}">“${esc(w.term)}” ${label}</span>`;}).join(''):'';
213	  const strong=q?scoreOf(b,parse(q))?.strong:true;
214	  return `<div class="card ${b.unread?'toread':''} ${b.archived?'archived':''} ${b.id===flashId?'flash':''}" data-id="${b.id}">
215	    ${rank?`<div class="rankno">${rank}</div>`:''}
216	    ${b.img?`<img class="thumb clickable" src="${b.img}" data-act="open">`:'<div class="thumb placeholder clickable" data-act="open">🔗</div>'}
217	    <div class="cardtools">${tools}</div>
218	    <div class="body"><div class="clickable" data-act="open">
219	      <div class="titlerow">${badges}<div class="title ${b.title?'':'untitled'}">${b.title?hlTerms(b.title,terms):'Untitled — add a title'}</div></div>
220	      <div class="url">${esc(b.url)}</div>
221	      <div class="desc">${b.desc?hlTerms(b.desc,terms):''}</div></div>
222	      <div class="why">${why}</div>
223	      ${(q&&!strong)?`<p class="snippet">${hlTerms(snippetFor(b,terms),terms)}</p>`:''}
224	      <div class="tags">${tags}</div>
225	    </div></div>`;
226	}
