228	function render(){
229	  renderViews(); renderLabelbar();
230	  const q=searchEl.value.trim(); const p=parse(q); const terms=allTerms(p); renderInterp(p);
231	  // scope note
232	  const parts=scopeText();
233	  if(q && parts.length){ scopeEl.classList.add('show'); scopeEl.innerHTML=`Searching within ${parts.join(' · ')}. <a id="searchAll">Search all bookmarks instead →</a>`; }
234	  else scopeEl.classList.remove('show');
