162	<script>
163	'use strict';
164	/* ---------- tiny IndexedDB store (durable, on this device) ---------- */
165	const DB = (() => {
166	  let dbp;
167	  function open() {
168	    if (dbp) return dbp;
169	    dbp = new Promise((res, rej) => {
170	      const r = indexedDB.open('mybookmarks', 1);
171	      r.onupgradeneeded = () => {
172	        const db = r.result;
173	        if (!db.objectStoreNames.contains('items')) db.createObjectStore('items', { keyPath: 'id' });
174	        if (!db.objectStoreNames.contains('meta')) db.createObjectStore('meta', { keyPath: 'k' });
175	      };
176	      r.onsuccess = () => res(r.result);
177	      r.onerror = () => rej(r.error);
178	    });
179	    return dbp;
180	  }
181	  function tx(store, mode, fn) {
182	    return open().then(db => new Promise((res, rej) => {
183	      const t = db.transaction(store, mode);
184	      const s = t.objectStore(store);
185	      const out = fn(s);
186	      t.oncomplete = () => res(out && out.result !== undefined ? out.result : out);
187	      t.onerror = () => rej(t.error);
188	    }));
189	  }
190	  return {
191	    all: () => tx('items', 'readonly', s => s.getAll()),
192	    put: (v) => tx('items', 'readwrite', s => s.put(v)),
193	    del: (id) => tx('items', 'readwrite', s => s.delete(id)),
194	    putMany: (vs) => tx('items', 'readwrite', s => { vs.forEach(v => s.put(v)); return true; }),
195	    metaGet: (k) => tx('meta', 'readonly', s => s.get(k)),
196	    metaPut: (k, val) => tx('meta', 'readwrite', s => s.put({ k, val })),
197	  };
198	})();
199	
200	/* ---------- url helpers ---------- */
201	function looksLikeUrl(raw) {
202	  if (raw == null) return null;
203	  let s = String(raw).trim(); if (!s || /\s/.test(s)) return null;
204	  if (!/^https?:\/\//i.test(s)) s = 'https://' + s;
205	  try { const u = new URL(s); if (!u.hostname.includes('.')) return null; return u.href; } catch { return null; }
206	}
207	function normUrl(raw) { let s = String(raw || '').trim().toLowerCase(); s = s.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, ''); return s; }
208	function guessTitle(url) {
209	  try {
210	    const u = new URL(url);
211	    const seg = u.pathname.split('/').filter(Boolean).pop();
212	    if (seg && !/^\d+$/.test(seg)) {
213	      const words = decodeURIComponent(seg).replace(/\.[a-z0-9]{1,5}$/i, '').replace(/[-_+]/g, ' ').trim();
214	      if (words) return words.replace(/\b\w/g, c => c.toUpperCase());
215	    }
216	    return u.hostname.replace(/^www\./, '');
217	  } catch { return ''; }
218	}
219	
220	/* ---------- search (ranking, loose multi-word, operators) ---------- */
221	const WEIGHTS = { title: 100, summary: 40, labels: 40, url: 20 };
222	const STRONG = new Set(['title', 'summary', 'labels']);
223	const EXCLUDE = new Set(['not', 'without', 'except']);
224	function fieldsOf(b) { return { title: b.title || '', summary: b.summary || '', labels: (b.labels || []).join(' '), url: b.url || '' }; }
225	function parseQuery(q) {
226	  const raw = String(q || '').match(/-?"[^"]*"|\S+/g) || [];
227	  const groups = [], negs = []; let pOr = false, pNeg = false;
228	  for (const r0 of raw) {
229	    let r = r0, neg = false, phrase = false;
230	    if (r[0] === '-') { neg = true; r = r.slice(1); }
231	    if (r[0] === '"') { phrase = true; r = r.replace(/^"|"$/g, ''); }
232	    const text = r.toLowerCase().trim(); if (!text) continue;
233	    if (!phrase && !neg) { if (text === 'or' && groups.length) { pOr = true; continue; } if (text === 'and') continue; if (EXCLUDE.has(text)) { pNeg = true; continue; } }
234	    if (neg || pNeg) { negs.push({ text }); pNeg = false; continue; }
235	    const tok = { text, phrase };
236	    if (pOr && groups.length) { groups[groups.length - 1].push(tok); pOr = false; } else groups.push([tok]);
237	  }
238	  return { groups, negs };
239	}
240	function scoreRecord(b, parsed) {
241	  const f = fieldsOf(b); const flat = Object.values(f).join('   ').toLowerCase();
242	  for (const n of parsed.negs) if (flat.includes(n.text)) return null;
243	  let total = 0; const why = [];
244	  for (const grp of parsed.groups) {
245	    let best = 0, bf = null, bt = null;
246	    for (const alt of grp) for (const k in f) if (f[k].toLowerCase().includes(alt.text)) if (WEIGHTS[k] > best) { best = WEIGHTS[k]; bf = k; bt = alt.text; }
247	    if (best === 0) return null;
248	    total += best; why.push({ term: bt, field: bf });
249	  }
250	  return { total, why, strong: why.some(w => STRONG.has(w.field)) };
251	}
252	function describe(parsed) {
253	  const chips = [];
254	  for (const g of parsed.groups) { if (g.length > 1) chips.push({ kind: 'either', text: g.map(t => t.text).join(' / ') }); else if (g[0].phrase) chips.push({ kind: 'phrase', text: g[0].text }); else chips.push({ kind: 'word', text: g[0].text }); }
255	  for (const n of parsed.negs) chips.push({ kind: 'without', text: n.text });
256	  return { chips, special: parsed.groups.some(g => g.length > 1 || g[0].phrase) || parsed.negs.length > 0 };
257	}
258	
259	/* ---------- import parsing (browser bookmarks HTML + our own JSON) ---------- */
260	function decodeEnt(s) { return String(s).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'"); }
261	function parseNetscape(html) {
262	  const items = [], stack = [];
263	  const re = /<h3[^>]*>([\s\S]*?)<\/h3>|<\/dl>|<a\s+([^>]*)>([\s\S]*?)<\/a>/gi; let m;
264	  while ((m = re.exec(html)) !== null) {
265	    if (m[1] !== undefined) stack.push(decodeEnt(m[1].replace(/<[^>]+>/g, '')).trim());
266	    else if (/^<\/dl>/i.test(m[0])) { if (stack.length) stack.pop(); }
267	    else if (m[2] !== undefined) {
268	      const href = (m[2].match(/href\s*=\s*"([^"]*)"/i) || [])[1];
269	      if (!href || /^(javascript|place):/i.test(href)) continue;
270	      const add = (m[2].match(/add_date\s*=\s*"([^"]*)"/i) || [])[1];
271	      let date = null; if (add) { const secs = parseInt(add, 10); if (secs > 0) { const ms = secs > 1e12 ? secs : secs * 1000; const d = new Date(ms); if (!isNaN(d)) date = d.toISOString(); } }
272	      items.push({ title: decodeEnt(m[3].replace(/<[^>]+>/g, '')).trim(), url: decodeEnt(href), folder: stack.length ? stack.join('/') : null, date });
273	    }
274	  }
275	  return items;
276	}
277	function foldersToLabels(f) { return f ? f.split('/').map(s => s.trim().toLowerCase()).filter(Boolean) : []; }
278	function parseFile(text) {
279	  try { const o = JSON.parse(text); if (o && Array.isArray(o.bookmarks)) return { kind: 'own', items: o.bookmarks }; } catch {}
280	  return { kind: 'netscape', items: parseNetscape(text) };
281	}
282	
283	/* ---------- app state ---------- */
284	let bookmarks = [];
285	const state = { view: 'all', label: null, query: '' };
286	let editingId = null, draftLabels = [], justSavedId = null, flashId = null, lastDeleted = null;
287	const $ = id => document.getElementById(id);
288	const esc = s => String(s == null ? '' : s).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
289	function highlight(t, terms) { let s = esc(t); (terms || []).forEach(x => { if (!x) return; const re = new RegExp('(' + x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'ig'); s = s.replace(re, '<mark>$1</mark>'); }); return s; }
290	function fmtDate(iso) { if (!iso) return ''; const d = new Date(iso); return isNaN(d) ? '' : 'saved ' + d.toLocaleDateString(undefined, { month: 'short', year: 'numeric' }); }
291	function uid() { return 'b_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
292	
293	/* ---------- backup nudge ---------- */
294	let changes = 0;
295	async function loadChanges() { const m = await DB.metaGet('changes'); changes = (m && m.val) || 0; refreshBackup(); }
296	function bumpChanges(n) { changes += (n || 1); DB.metaPut('changes', changes); refreshBackup(); }
297	function refreshBackup() {
298	  const show = bookmarks.length > 0 && changes >= 8;
299	  $('backup').classList.toggle('show', show);
300	}
301	
302	/* ---------- rendering ---------- */
303	const active = () => bookmarks.filter(b => !b.archived);
304	function counts() { const a = active(); return { all: a.length, toread: a.filter(b => b.unread).length, archived: bookmarks.filter(b => b.archived).length }; }
305	function labelList() { const s = new Set(); active().forEach(b => (b.labels || []).forEach(l => s.add(l))); return [...s].sort(); }
306	function scopedPool() {
307	  let pool = state.view === 'archived' ? bookmarks.filter(b => b.archived) : active();
308	  if (state.view === 'toread') pool = pool.filter(b => b.unread);
309	  if (state.view !== 'archived' && state.label) pool = pool.filter(b => (b.labels || []).includes(state.label));
310	  return pool;
311	}
312	function currentResults() {
313	  const pool = scopedPool();
314	  if (!state.query.trim()) {
315	    const items = pool.slice().sort((a, b) => String(b.savedAt).localeCompare(String(a.savedAt)));
316	    return { searching: false, items: items.map(b => ({ b })) };
317	  }
318	  const parsed = parseQuery(state.query);
319	  const scored = [];
320	  for (const b of pool) { const s = scoreRecord(b, parsed); if (s) scored.push({ b, ...s }); }
321	  scored.sort((a, b) => (b.total - a.total) || String(b.b.savedAt).localeCompare(String(a.b.savedAt)));
322	  return { searching: true, parsed, items: scored };
323	}
324	function render() {
325	  const c = counts();
326	  $('views').innerHTML =
327	    `<span class="view ${state.view === 'all' ? 'active' : ''}" data-view="all">All bookmarks <span class="n">${c.all}</span></span>` +
328	    `<span class="view toread ${state.view === 'toread' ? 'active' : ''}" data-view="toread">📖 To read <span class="n">${c.toread}</span></span>` +
329	    `<span class="view archived ${state.view === 'archived' ? 'active' : ''}" data-view="archived">🗄 Archived <span class="n">${c.archived}</span></span>`;
330	  const labels = labelList();
331	  $('labelbar').innerHTML = (state.view === 'archived' || !labels.length) ? '' :
332	    `<span class="lead">Labels:</span><span class="pill ${state.label === null ? 'active' : ''}" data-label="__all">All</span>` +
333	    labels.map(l => `<span class="pill ${state.label === l ? 'active' : ''}" data-label="${esc(l)}">${esc(l)}</span>`).join('');
334	  const res = currentResults();
335	  // scope bar
336	  const parts = [];
