cd /tmp && cat > test.js <<'EOF'
// ---- lifted verbatim from MyBookmarks.html ----
function looksLikeUrl(raw){ if(raw==null) return null; let s=String(raw).trim(); if(!s||/\s/.test(s)) return null; if(!/^https?:\/\//i.test(s)) s='https://'+s; try{const u=new URL(s); if(!u.hostname.includes('.')) return null; return u.href;}catch{return null;} }
function normUrl(raw){ let s=String(raw||'').trim().toLowerCase(); s=s.replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,''); return s; }
function guessTitle(url){ try{ const u=new URL(url); const seg=u.pathname.split('/').filter(Boolean).pop(); if(seg&&!/^\d+$/.test(seg)){ const words=decodeURIComponent(seg).replace(/\.[a-z0-9]{1,5}$/i,'').replace(/[-_+]/g,' ').trim(); if(words) return words.replace(/\b\w/g,c=>c.toUpperCase()); } return u.hostname.replace(/^www\./,''); }catch{return '';} }
function decodeEnt(s){ return String(s).replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'"); }
function parseNetscape(html){ const items=[],stack=[]; const re=/<h3[^>]*>([\s\S]*?)<\/h3>|<\/dl>|<a\s+([^>]*)>([\s\S]*?)<\/a>/gi; let m;
  while((m=re.exec(html))!==null){
    if(m[1]!==undefined) stack.push(decodeEnt(m[1].replace(/<[^>]+>/g,'')).trim());
    else if(/^<\/dl>/i.test(m[0])){ if(stack.length) stack.pop(); }
    else if(m[2]!==undefined){ const href=(m[2].match(/href\s*=\s*"([^"]*)"/i)||[])[1]; if(!href||/^(javascript|place):/i.test(href)) continue;
      const add=(m[2].match(/add_date\s*=\s*"([^"]*)"/i)||[])[1]; let date=null; if(add){const secs=parseInt(add,10); if(secs>0){const ms=secs>1e12?secs:secs*1000; const d=new Date(ms); if(!isNaN(d)) date=d.toISOString();}}
      items.push({ title:decodeEnt(m[3].replace(/<[^>]+>/g,'')).trim(), url:decodeEnt(href), folder:stack.length?stack.join('/'):null, date }); }
  } return items; }
function foldersToLabels(f){ return f?f.split('/').map(s=>s.trim().toLowerCase()).filter(Boolean):[]; }

const WEIGHTS={title:100,summary:40,labels:40,url:20}; const STRONG=new Set(['title','summary','labels']); const EXCLUDE=new Set(['not','without','except']);
function fieldsOf(b){ return {title:b.title||'',summary:b.summary||'',labels:(b.labels||[]).join(' '),url:b.url||''}; }
function parseQuery(q){ const raw=String(q||'').match(/-?"[^"]*"|\S+/g)||[]; const groups=[],negs=[]; let pOr=false,pNeg=false;
  for(const r0 of raw){ let r=r0,neg=false,phrase=false; if(r[0]==='-'){neg=true;r=r.slice(1);} if(r[0]==='"'){phrase=true;r=r.replace(/^"|"$/g,'');} const text=r.toLowerCase().trim(); if(!text) continue;
    if(!phrase&&!neg){ if(text==='or'&&groups.length){pOr=true;continue;} if(text==='and') continue; if(EXCLUDE.has(text)){pNeg=true;continue;} }
    if(neg||pNeg){negs.push({text});pNeg=false;continue;} const tok={text,phrase}; if(pOr&&groups.length){groups[groups.length-1].push(tok);pOr=false;} else groups.push([tok]); }
  return {groups,negs}; }
function scoreRecord(b,parsed){ const f=fieldsOf(b); const flat=Object.values(f).join('   ').toLowerCase(); for(const n of parsed.negs) if(flat.includes(n.text)) return null; let total=0; const why=[];
  for(const grp of parsed.groups){ let best=0,bf=null,bt=null; for(const alt of grp) for(const k in f) if(f[k].toLowerCase().includes(alt.text)) if(WEIGHTS[k]>best){best=WEIGHTS[k];bf=k;bt=alt.text;} if(best===0) return null; total+=best; why.push({term:bt,field:bf}); }
  return {total,why,strong:why.some(w=>STRONG.has(w.field))}; }

// ---- a realistic browser export (Netscape), with nesting, a dup, entities, a date ----
const file=`<!DOCTYPE NETSCAPE-Bookmark-file-1><DL><p>
<DT><H3>Cooking</H3><DL><p>
  <DT><A HREF="https://kitchenlab.example/no-knead-bread" ADD_DATE="1572652800">No-Knead Bread</A>
  <DT><A HREF="https://kitchenlab.example/sourdough" ADD_DATE="1466208000">Sourdough &amp; Rye Guide</A>
  <DT><A HREF="https://kitchenlab.example/no-knead-bread" ADD_DATE="1600000000">No-Knead Bread (again)</A>
</DL><p>
<DT><H3>Reading</H3><DL><p>
  <DT><H3>Longform</H3><DL><p>
    <DT><A HREF="https://blog.example/on-attention" ADD_DATE="1696032000">On Attention</A>
  </DL><p>
  <DT><A HREF="https://readingnook.example/why-we-sleep">Why We Sleep</A>
</DL><p>
<DT><A HREF="https://travelmore.example/lisbon" ADD_DATE="1552262400">12 Hidden Gems in Lisbon</A>
</DL><p>`;
