function looksLikeUrl(raw){ if(raw==null) return null; let s=String(raw).trim(); if(!s||/\s/.test(s)) return null; if(!/^https?:\/\//i.test(s)) s='https://'+s; try{const u=new URL(s); if(!u.hostname.includes('.')) return null; return u.href;}catch{return null;} }
function normUrl(raw){ let s=String(raw||'').trim().toLowerCase(); s=s.replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,''); return s; }
function guessTitle(url){ try{const u=new URL(url);return u.hostname.replace(/^www\./,'');}catch{return '';} }

// my live collection after move-in + some edits
let bookmarks=[
  {id:uid(),url:'https://kitchenlab.example/no-knead-bread',title:'No-Knead Bread',summary:'crackly crust, dutch oven',labels:['cooking'],unread:false,archived:false,savedAt:'2019-11-02T00:00:00.000Z'},
