const fileText=JSON.stringify(data,null,2);

// ---- simulate: browser wiped, app opens EMPTY, user imports the backup ----
function parseFile(text){ try{const o=JSON.parse(text); if(o&&Array.isArray(o.bookmarks)) return {kind:'own',items:o.bookmarks};}catch{} return {kind:'netscape',items:[]}; }
let restored=[]; const seen=new Set(restored.map(b=>normUrl(b.url)));
