function bumpChanges(n) { changes += (n || 1); DB.metaPut('changes', changes); refreshBackup(); }
function refreshBackup() {
  const show = bookmarks.length > 0 && changes >= 8;
  $('backup').classList.toggle('show', show);
}
// Once you've ever had bookmarks, remember it — so an empty screen can reassure rather than look like a fresh start.
function markEver() { if (!everHadData && bookmarks.length > 0) { everHadData = true; DB.metaPut('everHadData', true); } }
function relTime(iso) {
  if (!iso) return null;
  const day = d => { const x = new Date(d); x.setHours(0, 0, 0, 0); return x.getTime(); };
  const days = Math.round((day(new Date()) - day(iso)) / 86400000);
  if (days <= 0) return 'today'; if (days === 1) return 'yesterday'; return days + ' days ago';
}
function renderBackupStatus() {
  const el = $('backupStatus'); if (!el) return;
  if (bookmarks.length === 0) { el.textContent = ''; el.className = 'backupstatus'; return; }
  const rt = relTime(lastBackupAt);
  if (!rt) { el.innerHTML = '⚠ Not backed up yet — <a id="statusBackup">save a backup</a> you can\'t lose.'; el.className = 'backupstatus warn'; }
  else {
    const stale = (Date.now() - new Date(lastBackupAt).getTime()) > 7 * 86400000;
    el.innerHTML = 'Last backup: ' + rt + (stale ? ' — <a id="statusBackup">worth doing again</a>' : '');
    el.className = 'backupstatus' + (stale ? ' warn' : '');
  }
  const b = $('statusBackup'); if (b) b.onclick = exportAll;
}

/* ---------- rendering ---------- */
const active = () => bookmarks.filter(b => !b.archived);
function counts() { const a = active(); return { all: a.length, toread: a.filter(b => b.unread).length, archived: bookmarks.filter(b => b.archived).length }; }
function labelList() { const s = new Set(); active().forEach(b => (b.labels || []).forEach(l => s.add(l))); return [...s].sort(); }

